"""Module location.

Secret: how an imported module name is found — first as a source file or
package in the project directory, otherwise by importing a standard library
module at runtime (with its side effects contained) — and how the module
names importable from a place are enumerated.
"""

import contextlib
import importlib
import io
import os
import pkgutil
import sys
import sysconfig

SOURCE = "source"
RUNTIME = "runtime"
DIRECTORY = "directory"


class Located:
    """Where a module lives: a source file, a bare directory, or a live module."""

    def __init__(self, how, path=None, module=None):
        self.how = how
        self.path = path
        self.module = module


class ModuleLocator:
    def __init__(self, project_dir):
        self._project_dir = os.path.abspath(project_dir)
        self._runtime_cache = {}

    def locate(self, dotted, level=0, importer_path=None):
        """Locate ``dotted`` (relative to ``importer_path`` when ``level`` > 0)."""
        parts = [p for p in dotted.split(".") if p] if dotted else []
        if level > 0:
            base = self.relative_base(level, importer_path)
            return self._locate_in(base, parts) if base is not None else None
        if not parts:
            return None
        namespace = None
        for root in self.search_roots(importer_path):
            found = self._locate_in(root, parts)
            if found is not None and found.how == SOURCE:
                return found
            namespace = namespace or found
        if namespace is not None and _holds_python(namespace.path):
            return namespace
        module = self._import_runtime(".".join(parts))
        if module is not None:
            return Located(RUNTIME, module=module)
        return namespace

    def relative_base(self, level, importer_path):
        """Directory a relative import of ``level`` dots starts from, or None
        when it would leave the project."""
        base = os.path.dirname(os.path.abspath(importer_path or self._project_dir))
        for _ in range(level - 1):
            base = os.path.dirname(base)
        if base != self._project_dir and not base.startswith(
                self._project_dir.rstrip(os.sep) + os.sep):
            return None
        return base

    def search_roots(self, importer_path=None):
        roots = [self._project_dir]
        if importer_path:
            own = os.path.dirname(os.path.abspath(importer_path))
            if own not in roots:
                roots.append(own)
        return roots

    def top_level_names(self, importer_path=None):
        """Names of the modules ``import <name>`` can find."""
        names = set()
        for root in self.search_roots(importer_path):
            names.update(directory_module_names(root))
        names.update(stdlib_names())
        return names

    def locate_in_directory(self, directory, name):
        """Locate submodule ``name`` of the package stored in ``directory``."""
        return self._locate_in(directory, [name])

    def _locate_in(self, base, parts):
        path = base
        for index, part in enumerate(parts):
            last = index == len(parts) - 1
            package = os.path.join(path, part)
            regular = os.path.isfile(os.path.join(package, "__init__.py"))
            if os.path.isdir(package) and (regular or not os.path.isfile(package + ".py")):
                if last:
                    return self._package(package)
                path = package
                continue
            if last and os.path.isfile(package + ".py"):
                return Located(SOURCE, path=package + ".py")
            return None
        return self._package(path)

    @staticmethod
    def _package(directory):
        init = os.path.join(directory, "__init__.py")
        if os.path.isfile(init):
            return Located(SOURCE, path=init)
        return Located(DIRECTORY, path=directory)

    def _import_runtime(self, name):
        if name in self._runtime_cache:
            return self._runtime_cache[name]
        if not _is_stdlib(name):
            self._runtime_cache[name] = None
            return None
        module = None
        saved_path = list(sys.path)
        sys.path[:] = [p for p in sys.path
                       if p and os.path.abspath(p) not in (self._project_dir, _TOOL_DIR)]
        try:
            with _silenced_descriptors(), contextlib.redirect_stdout(io.StringIO()), \
                    contextlib.redirect_stderr(io.StringIO()):
                module = importlib.import_module(name)
        except BaseException:  # noqa: B902 - arbitrary import code may do anything
            module = None
        finally:
            sys.path[:] = saved_path
        self._runtime_cache[name] = module
        return module


@contextlib.contextmanager
def _silenced_descriptors():
    """Route OS-level stdout/stderr to the null device (for C extensions)."""
    saved = []
    try:
        sys.stdout.flush()
        sys.stderr.flush()
        devnull = os.open(os.devnull, os.O_WRONLY)
        for fd in (1, 2):
            saved.append((fd, os.dup(fd)))
            os.dup2(devnull, fd)
        os.close(devnull)
    except (OSError, ValueError, AttributeError):
        pass
    try:
        yield
    finally:
        for fd, copy in saved:
            os.dup2(copy, fd)
            os.close(copy)


_TOOL_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Standard library modules never imported for analysis (they act on import).
_UNSAFE = ("antigravity", "this", "__main__", "idlelib.idle", "idlelib.__main__")


def _is_stdlib(name):
    if name in _UNSAFE or name.endswith(".__main__"):
        return False
    top = name.split(".")[0]
    return top in getattr(sys, "stdlib_module_names", ()) or top in sys.builtin_module_names


_STDLIB_NAMES = None


def stdlib_names():
    """Top-level standard library modules available in this runtime."""
    global _STDLIB_NAMES
    if _STDLIB_NAMES is None:
        known = set(getattr(sys, "stdlib_module_names", ())) | set(sys.builtin_module_names)
        found = set(sys.builtin_module_names)
        directories = []
        for key in ("stdlib", "platstdlib"):
            path = sysconfig.get_paths().get(key)
            if path:
                directories += [path, os.path.join(path, "lib-dynload")]
        directories += [os.path.dirname(os.__file__)]
        directories = [d for d in dict.fromkeys(directories) if os.path.isdir(d)]
        try:
            found.update(info.name for info in pkgutil.iter_modules(directories))
        except (OSError, ImportError):
            pass
        _STDLIB_NAMES = {n for n in found & known if n not in _UNSAFE}
    return set(_STDLIB_NAMES)


def _holds_python(directory, depth=3):
    """Whether a namespace directory contains Python sources (near the top)."""
    try:
        entries = os.listdir(directory)
    except OSError:
        return False
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            return True
        if depth > 1 and entry.isidentifier() and os.path.isdir(path) \
                and _holds_python(path, depth - 1):
            return True
    return False


def directory_module_names(directory):
    """Modules and packages (regular or namespace) stored directly in ``directory``."""
    names = set()
    try:
        entries = os.listdir(directory)
    except OSError:
        return names
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            name = entry[:-3]
        elif os.path.isdir(path):
            name = entry
        else:
            continue
        if name.isidentifier() and name not in ("__init__", "__pycache__", "__main__"):
            names.add(name)
    return names


def runtime_submodule_names(module):
    """Submodules of a live package."""
    path = getattr(module, "__path__", None)
    if not path:
        return set()
    try:
        return {info.name for info in pkgutil.iter_modules(list(path))
                if info.name.isidentifier() and info.name != "__main__"}
    except (OSError, ImportError, TypeError):
        return set()
"""Scope and binding model.

Secret: how name bindings are discovered in a syntax tree, which scope they
belong to, and the rules (indentation heuristics included) that decide which
scope encloses a cursor and which bindings are visible from it.
"""

import ast
import re

from . import parsing

# Binding forms exposed to clients.
DEF = "def"
CLASS = "class"
PARAM = "param"
ASSIGN = "assign"
IMPORT = "import"
IMPORT_FROM = "import_from"
STAR = "star"
EXCEPT = "except"
OTHER = "other"


class Binding:
    """One event that binds a name (or, for STAR, a set of names)."""

    def __init__(self, name, form, line, order, scope, node=None, position=None,
                 stmt=None, home=None, **details):
        self.name = name
        self.form = form
        self.line = line
        self.order = order
        self.scope = scope
        # where the bound identifier itself is written: (1-based line, 0-based column)
        self.position = position or (line, 0)
        # the syntax node naming the binding, the statement (or handler/case)
        # that performs it, and the scope whose code contains that statement
        self.node = node
        self.stmt = stmt
        self.home = home or scope
        # form-specific details:
        #   DEF/CLASS: node
        #   PARAM: function (Scope), index, annotation, default, star ("", "*", "**"),
        #          keyword_only (optional)
        #   ASSIGN: value (expr or None), path (tuple of ints), annotation,
        #           owner (class Scope, for instance attributes), starred
        #   OTHER: source ("for"/"with"/None), value (iterable/context expr), path
        #   IMPORT: module (dotted name bound), as_name (bool)
        #   IMPORT_FROM: module, level, attr
        #   STAR: module, level
        #   EXCEPT: type_expr
        self.details = details


class Scope:
    MODULE, FUNCTION, CLASS = "module", "function", "class"

    def __init__(self, kind, node, parent, tree):
        self.kind = kind
        self.node = node
        self.parent = parent
        self.tree = tree
        self.children = []
        self.events = []
        self.instance_events = []  # self.<attr> assignments in methods (classes)
        self.globals_declared = set()

    @property
    def name(self):
        return getattr(self.node, "name", None)

    def class_scope(self):
        """For a method, the scope of the class that defines it."""
        if self.kind == Scope.FUNCTION and self.parent is not None \
                and self.parent.kind == Scope.CLASS:
            return self.parent
        return None

    def decorator_names(self):
        names = []
        for deco in getattr(self.node, "decorator_list", []):
            if isinstance(deco, ast.Name):
                names.append(deco.id)
            elif isinstance(deco, ast.Attribute):
                names.append(deco.attr)
        return names

    def returned_expressions(self):
        """Return-value expressions of a function (excluding nested scopes)."""
        found = []
        for node in _walk_own(self.node.body if self.node is not None else []):
            if isinstance(node, (ast.Yield, ast.YieldFrom)):
                return []
            if isinstance(node, ast.Return) and node.value is not None:
                found.append(node.value)
        return found

    def return_statements(self):
        """``return`` statements of a function, or None for generators."""
        found = []
        for node in _walk_own(self.node.body if self.node is not None else []):
            if isinstance(node, (ast.Yield, ast.YieldFrom)):
                return None
            if isinstance(node, ast.Return):
                found.append(node)
        return found

    def base_expressions(self):
        return list(getattr(self.node, "bases", []))

    def is_async(self):
        return isinstance(self.node, ast.AsyncFunctionDef)

    def chain(self):
        """Scopes searched for names from here: self, enclosing functions, module."""
        result = [self]
        scope = self.parent
        while scope is not None:
            if scope.kind != Scope.CLASS:
                result.append(scope)
            scope = scope.parent
        return result

    def events_until_line(self, line):
        return [e for e in self.events if e.line <= line]

    def events_before(self, order):
        return [e for e in self.events if e.order < order]

    def all_events(self):
        return list(self.events)

    def instance_attribute_events(self):
        return list(self.instance_events)


class ScopeTree:
    def __init__(self, text, path=None):
        self.path = path
        self._lines = text.split("\n")
        module = parsing.parse_tolerant(text)
        self.module = Scope(Scope.MODULE, module, None, self)
        _Collector(self.module).visit_body(module.body)

    def line_text(self, line):
        return self._lines[line - 1] if 0 < line <= len(self._lines) else ""

    def segment(self, node):
        """Source text of ``node`` (as written), or None."""
        try:
            first, last = node.lineno, node.end_lineno
            if last is None or first > len(self._lines):
                return None
            if first == last:
                return self._lines[first - 1][node.col_offset:node.end_col_offset]
            parts = [self._lines[first - 1][node.col_offset:]]
            parts.extend(self._lines[first:last - 1])
            parts.append(self._lines[last - 1][:node.end_col_offset])
            return "\n".join(parts)
        except (AttributeError, IndexError, TypeError):
            return None

    def find_identifier(self, name, line, col, after_keyword=None):
        """Position of identifier ``name`` at or after (line, col).

        With ``after_keyword`` the identifier must follow that keyword.
        """
        pattern = re.compile((r"\b%s\s+" % after_keyword if after_keyword else r"(?<![\w.])")
                             + r"(%s)\b" % re.escape(name))
        for number in range(line, min(line + 50, len(self._lines)) + 1):
            text = self._lines[number - 1]
            start = col if number == line else 0
            match = pattern.search(text, start)
            if match:
                return number, match.start(1)
        return line, col

    def definition_position(self, node):
        """Position of the name in a ``def``/``class`` header."""
        keyword = "class" if isinstance(node, ast.ClassDef) else "def"
        return self.find_identifier(node.name, node.lineno, node.col_offset, keyword)

    def scope_at(self, line, col):
        scope = self.module
        while True:
            inner = None
            for child in scope.children:
                if self._contains(child, line, col):
                    inner = child
            if inner is None:
                return scope
            scope = inner

    def _contains(self, scope, line, col):
        node = scope.node
        header, end = node.lineno, node.end_lineno or node.lineno
        header_col = node.col_offset
        body = node.body[0] if node.body else None
        if line < header:
            return False
        if line == header:
            return body is not None and body.lineno == header and col >= body.col_offset
        text = self._lines[line - 1] if line - 1 < len(self._lines) else ""
        before = text[:col]
        indent = _indent_width(text) if before.strip() else col
        if indent <= header_col and (line > end or not before.strip()):
            return False
        if line <= end:
            return True
        for number in range(end + 1, line):
            other = self._lines[number - 1] if number - 1 < len(self._lines) else ""
            stripped = other.strip()
            if stripped and not stripped.startswith("#") and _indent_width(other) <= header_col:
                return False
        return True


def _indent_width(text):
    return len(text) - len(text.lstrip())


def _walk_own(statements):
    """Walk nodes in ``statements`` without entering nested scopes."""
    stack = list(reversed(statements))
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(node))))


class _Counter:
    value = 0

    @classmethod
    def next(cls):
        cls.value += 1
        return cls.value


class _Collector(ast.NodeVisitor):
    def __init__(self, scope):
        self.scope = scope
        self.stmt = None

    def visit(self, node):
        if isinstance(node, (ast.stmt, ast.ExceptHandler, ast.match_case)):
            saved, self.stmt = self.stmt, node
            try:
                return super().visit(node)
            finally:
                self.stmt = saved
        return super().visit(node)

    # -- helpers ---------------------------------------------------------
    def visit_body(self, statements):
        for statement in statements:
            self.visit(statement)

    def _target_scope(self, name):
        if name in self.scope.globals_declared:
            scope = self.scope
            while scope.parent is not None:
                scope = scope.parent
            return scope
        return self.scope

    def bind(self, name, form, line, node=None, position=None, **details):
        scope = self._target_scope(name) if name else self.scope
        binding = Binding(name, form, line, _Counter.next(), scope, node=node,
                          position=position, stmt=self.stmt, home=self.scope, **details)
        scope.events.append(binding)
        return binding

    def bind_target(self, target, line, value, path=(), annotation=None, starred=False):
        if isinstance(target, ast.Name):
            self.bind(target.id, ASSIGN, line, node=target, position=_start(target),
                      value=value, path=path, annotation=annotation, starred=starred)
        elif isinstance(target, (ast.Tuple, ast.List)):
            for index, element in enumerate(target.elts):
                self.bind_target(element, line, value, path + (index,))
        elif isinstance(target, ast.Starred):
            self.bind_target(target.value, line, None, starred=True)
        else:
            self.visit(target)

    def bind_plain(self, target, line, source=None, value=None, path=()):
        if isinstance(target, ast.Name):
            self.bind(target.id, OTHER, line, node=target, position=_start(target),
                      source=source, value=value, path=path)
        elif isinstance(target, (ast.Tuple, ast.List)):
            for index, element in enumerate(target.elts):
                self.bind_plain(element, line, source, value, path + (index,))
        elif isinstance(target, ast.Starred):
            self.bind_plain(target.value, line)
        else:
            for node in ast.walk(target):
                if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                    self.bind(node.id, OTHER, line, node=node, position=_start(node))

    # -- scopes ----------------------------------------------------------
    def _visit_function(self, node):
        for deco in node.decorator_list:
            self.visit(deco)
        args = node.args
        for default in args.defaults + [d for d in args.kw_defaults if d is not None]:
            self.visit(default)
        tree = self.scope.tree
        self.bind(node.name, DEF, node.lineno, node=node,
                  position=tree.definition_position(node))
        child = Scope(Scope.FUNCTION, node, self.scope, tree)
        self.scope.children.append(child)
        positional = args.posonlyargs + args.args
        defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
        index = 0
        for arg, default in zip(positional, defaults):
            child_bind(child, arg, node, function=child, index=index,
                       annotation=arg.annotation, default=default, star="")
            index += 1
        if args.vararg:
            child_bind(child, args.vararg, node, function=child, index=index,
                       annotation=None, default=None, star="*")
            index += 1
        for arg, default in zip(args.kwonlyargs, args.kw_defaults):
            child_bind(child, arg, node, function=child, index=index,
                       annotation=arg.annotation, default=default, star="", keyword_only=True)
            index += 1
        if args.kwarg:
            child_bind(child, args.kwarg, node, function=child, index=index,
                       annotation=None, default=None, star="**")
        collector = _Collector(child)
        for statement in _walk_own(node.body):
            if isinstance(statement, ast.Global):
                child.globals_declared.update(statement.names)
        collector.visit_body(node.body)
        parent_class = child.class_scope()
        if parent_class is not None and positional:
            decorators = child.decorator_names()
            if "staticmethod" not in decorators and "classmethod" not in decorators:
                self_name = positional[0].arg
                _collect_instance_attributes(parent_class, child, node.body, self_name,
                                             initializer=node.name == "__init__")

    visit_FunctionDef = _visit_function
    visit_AsyncFunctionDef = _visit_function

    def visit_ClassDef(self, node):
        for deco in node.decorator_list:
            self.visit(deco)
        for base in node.bases:
            self.visit(base)
        tree = self.scope.tree
        self.bind(node.name, CLASS, node.lineno, node=node,
                  position=tree.definition_position(node))
        child = Scope(Scope.CLASS, node, self.scope, tree)
        self.scope.children.append(child)
        _Collector(child).visit_body(node.body)

    def visit_Lambda(self, node):
        pass

    def _visit_comprehension(self, node):
        for generator in node.generators:
            self.visit(generator.iter)
            break

    visit_ListComp = _visit_comprehension
    visit_SetComp = _visit_comprehension
    visit_DictComp = _visit_comprehension
    visit_GeneratorExp = _visit_comprehension

    # -- statements ------------------------------------------------------
    def visit_Global(self, node):
        self.scope.globals_declared.update(node.names)

    def visit_Assign(self, node):
        self.visit(node.value)
        for target in node.targets:
            self.bind_target(target, node.lineno, node.value)

    def visit_AnnAssign(self, node):
        if node.value is not None:
            self.visit(node.value)
        if isinstance(node.target, ast.Name):
            self.bind(node.target.id, ASSIGN, node.lineno, node=node.target,
                      position=_start(node.target), value=node.value, path=(),
                      annotation=node.annotation)
        else:
            self.visit(node.target)

    def visit_AugAssign(self, node):
        self.visit(node.value)
        if isinstance(node.target, ast.Name):
            name = node.target.id
            scope = self._target_scope(name)
            if not any(e.name == name for e in scope.events):
                self.bind(name, OTHER, node.lineno, node=node.target,
                          position=_start(node.target))
        else:
            self.visit(node.target)

    def visit_NamedExpr(self, node):
        self.visit(node.value)
        if isinstance(node.target, ast.Name):
            self.bind(node.target.id, ASSIGN, node.lineno, node=node.target,
                      position=_start(node.target), value=node.value, path=(),
                      annotation=None)

    def _visit_for(self, node):
        self.visit(node.iter)
        self.bind_plain(node.target, node.lineno, "for", node.iter)
        self.visit_body(node.body)
        self.visit_body(node.orelse)

    visit_For = _visit_for
    visit_AsyncFor = _visit_for

    def _visit_with(self, node):
        for item in node.items:
            self.visit(item.context_expr)
            if item.optional_vars is not None:
                self.bind_plain(item.optional_vars, node.lineno, "with", item.context_expr)
        self.visit_body(node.body)

    visit_With = _visit_with
    visit_AsyncWith = _visit_with

    def visit_ExceptHandler(self, node):
        if node.type is not None:
            self.visit(node.type)
        if node.name:
            tree = self.scope.tree
            position = tree.find_identifier(node.name, node.lineno, node.col_offset, "as")
            self.bind(node.name, EXCEPT, node.lineno, node=node, position=position,
                      type_expr=node.type)
        self.visit_body(node.body)

    def visit_Import(self, node):
        for alias in node.names:
            if alias.asname:
                self.bind(alias.asname, IMPORT, node.lineno, node=alias,
                          position=_as_position(alias), module=alias.name, as_name=True)
            else:
                first = alias.name.split(".")[0]
                self.bind(first, IMPORT, node.lineno, node=alias, position=_start(alias),
                          module=first, as_name=False)

    def visit_ImportFrom(self, node):
        module = node.module or ""
        for alias in node.names:
            if alias.name == "*":
                self.bind(None, STAR, node.lineno, node=alias, module=module, level=node.level)
            else:
                position = _as_position(alias) if alias.asname else _start(alias)
                self.bind(alias.asname or alias.name, IMPORT_FROM, node.lineno, node=alias,
                          position=position, module=module, level=node.level, attr=alias.name)

    def visit_MatchAs(self, node):
        if node.pattern is not None:
            self.visit(node.pattern)
        if node.name:
            position = (node.end_lineno, node.end_col_offset - len(node.name))
            self.bind(node.name, OTHER, node.lineno, node=node, position=position)

    def visit_MatchStar(self, node):
        if node.name:
            position = (node.end_lineno, node.end_col_offset - len(node.name))
            self.bind(node.name, OTHER, node.lineno, node=node, position=position)

    def visit_MatchMapping(self, node):
        self.generic_visit(node)
        if node.rest:
            position = self.scope.tree.find_identifier(node.rest, node.lineno, node.col_offset)
            self.bind(node.rest, OTHER, node.lineno, node=node, position=position)

    def visit_TypeAlias(self, node):
        if isinstance(node.name, ast.Name):
            self.bind(node.name.id, OTHER, node.lineno, node=node.name,
                      position=_start(node.name))


def _start(node):
    return (getattr(node, "lineno", 1), getattr(node, "col_offset", 0))


def _as_position(alias):
    """Position of the ``as`` name of an import alias."""
    return (alias.end_lineno, alias.end_col_offset - len(alias.asname))


def child_bind(scope, arg, function_node, **details):
    scope.events.append(Binding(arg.arg, PARAM, function_node.lineno, _Counter.next(), scope,
                                node=arg, position=_start(arg), stmt=function_node,
                                home=scope, **details))


def _collect_instance_attributes(class_scope, method_scope, body, self_name, initializer):
    """Record ``<self>.<attr> = ...`` assignments of a method on its class."""
    found = []

    def is_self_attr(target):
        return (isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name)
                and target.value.id == self_name)

    def record(target, statement, value, path, annotation=None):
        if is_self_attr(target):
            found.append(Binding(
                target.attr, ASSIGN, statement.lineno, _Counter.next(), method_scope,
                node=target, position=(target.end_lineno,
                                       target.end_col_offset - len(target.attr)),
                stmt=statement, home=method_scope, value=value, path=path,
                annotation=annotation, owner=class_scope))
        elif isinstance(target, (ast.Tuple, ast.List)):
            for index, element in enumerate(target.elts):
                record(element, statement, value, path + (index,))
        elif isinstance(target, ast.Starred):
            record(target.value, statement, None, ())

    for node in _walk_own(body):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                record(target, node, node.value, ())
        elif isinstance(node, ast.AnnAssign):
            record(node.target, node, node.value, (), node.annotation)
        elif isinstance(node, ast.AugAssign) and is_self_attr(node.target):
            if not any(e.name == node.target.attr for e in class_scope.instance_events + found):
                target = node.target
                found.append(Binding(
                    target.attr, OTHER, node.lineno, _Counter.next(), method_scope,
                    node=target, position=(target.end_lineno,
                                           target.end_col_offset - len(target.attr)),
                    stmt=node, home=method_scope, owner=class_scope))
    if initializer:
        class_scope.instance_events[:0] = found
    else:
        class_scope.instance_events.extend(found)

"""Definition navigation (``goto`` and ``infer``).

Secret: how the identifier under the cursor is found and classified (plain
name, attribute, definition header, parameter, import part, keyword
argument, comprehension variable), what each command answers for it, and
how bindings and values are described as definition records (names,
qualified names, positions, descriptions, docstrings).
"""

import ast
import inspect
import os
import re
import types

from . import flow, inference, introspect, scopes
from .inference import (DictInstance, DirectoryModule, RuntimeEntity, RuntimeInstance,
                        RuntimeValue, StaticClass, StaticFunction, StaticInstance,
                        StaticModule, Where)
from .source import SourceFile

GOTO = "goto"
INFER = "infer"


class NotOnName(Exception):
    """The cursor does not touch an identifier."""


def run(command, path, line, col, root=None, follow_imports=False):
    """Definitions (as dicts) answering ``command`` at the cursor.

    With ``follow_imports``, ``goto`` continues through import statements to
    the definitions they finally name.
    """
    source = SourceFile(path)
    source.check_position(line, col)
    project = inference.Project(source.path, source.text(), root)
    analysis = project.main
    occurrence = _Finder(analysis, line, col).find()
    if occurrence is None:
        raise NotOnName("no name at %d:%d" % (line, col))
    describer = _Describer(project)
    if command == GOTO:
        targets = occurrence.goto()
        if follow_imports:
            targets = _Follower(project).follow(targets)
        records = describer.targets(targets)
    else:
        records = describer.values(occurrence.infer())
    unique = {}
    for record in records:
        if record is not None:
            unique.setdefault(tuple(sorted(record.items())), record)
    return sorted(unique.values(),
                  key=lambda r: (r["module_path"], r["line"], r["column"], r["name"]))


# ---------------------------------------------------------------------------
# Finding the identifier under the cursor

class _Occurrence:
    """One identifier in the main file and what it means."""

    def __init__(self, analysis, kind, node, scope, stmt, conditions=(), comprehension=None,
                 **extra):
        self.analysis = analysis
        self.kind = kind
        self.node = node
        self.scope = scope
        self.stmt = stmt
        self.conditions = list(conditions)  # narrowing from enclosing and/or/if-else
        self.comprehension = comprehension or {}  # visible comprehension variables
        self.extra = extra

    def where(self):
        if self.stmt is None:
            where = Where(self.scope)
        else:
            where = self.analysis.where_before(self.scope, self.stmt)
        if self.conditions:
            state = where.state if where.state is not None \
                else self.analysis.flow(self.scope).end
            where.state = state.narrowed(self.conditions)
        return self._with_comprehension(where, self.comprehension)

    def _with_comprehension(self, base, visible):
        if not visible:
            return base
        local = {name: self._comprehension_values(info, base) for name, info in visible.items()}
        return Where(base.scope, base.state, base.frame, local)

    def _comprehension_values(self, info, base):
        generator, _, path, before = info
        if path is None:
            return []
        where = self._with_comprehension(base, before)
        values = self.analysis.evaluate(generator.iter, where)
        return self.analysis.index_path([v for value in values for v in value.iterate()], path)

    # Results: goto gives targets (Bindings, Entities, value targets), infer values.
    def goto(self):
        return self._answer(GOTO)

    def infer(self):
        return self._answer(INFER)

    def _answer(self, command):
        analysis = self.analysis
        kind = self.kind
        binding = self.extra.get("binding")
        if binding is not None:
            if command == GOTO:
                return [binding]
            return analysis.binding_values(binding)
        if kind == "name":
            return self._name(command, self.node.id, self.where())
        if kind == "global":
            module = self.scope
            while module.parent is not None:
                module = module.parent
            return self._name(command, self.extra["name"], Where(module))
        if kind == "attr":
            receivers = analysis.evaluate(self.node.value, self.where())
            result = []
            for receiver in receivers:
                if command == GOTO:
                    result.extend(receiver.attribute_targets(self.node.attr))
                else:
                    result.extend(receiver.attribute(self.node.attr))
            return result
        if kind == "module":
            found = analysis.project.module_value(self.extra["dotted"], self.extra["level"],
                                                  analysis.path)
            if found is None:
                return []
            return [inference.ValueTarget(found)] if command == GOTO else [found]
        if kind == "imported":
            import_binding = self.extra["import_binding"]
            if command == GOTO:
                targets = analysis.import_from_targets(import_binding)
                if targets:
                    return targets
                return [inference.ValueTarget(v)
                        for v in analysis.binding_values(import_binding)]
            return analysis.binding_values(import_binding)
        if kind == "keyword":
            params = self._keyword_params()
            if command == GOTO:
                return params
            return [v for p in params for v in analysis.binding_values(p)]
        if kind == "comprehension":
            info = self.comprehension[self.node.id]
            if command == GOTO:
                return [_ComprehensionTarget(self.analysis, info[0], info[1])]
            return self._comprehension_values(info, self.where())
        return []

    def _name(self, command, name, where):
        analysis = self.analysis
        if command == GOTO:
            return [target for target, _ in analysis.resolve(name, where)]
        return analysis.name_values(name, where)

    def _keyword_params(self):
        analysis = self.analysis
        name = self.node.arg
        functions = []
        for value in analysis.evaluate(self.extra["call"].func, self.where()):
            if isinstance(value, StaticFunction):
                functions.append(value)
            elif isinstance(value, StaticClass):
                functions.extend(v for v in value.attribute("__init__")
                                 if isinstance(v, StaticFunction))
        params = []
        for function in functions:
            params.extend(e for e in function.scope.events
                          if e.form == scopes.PARAM and e.name == name)
        return params


class _Follower:
    """Follows import bindings to the definitions they import."""

    def __init__(self, project):
        self.project = project

    def follow(self, targets):
        result = []
        for target in targets:
            followed = self._follow(target, set())
            result.extend(followed if followed is not None else [target])
        return result

    def _follow(self, target, seen):
        """Final targets for ``target``, or None when the chain is broken."""
        if isinstance(target, inference.BindingEntity):
            target = target.binding
        if isinstance(target, inference.ValueEntity):
            values = target.values()
            if not values:
                return None
            found = [self._follow(inference.ValueTarget(v), seen) for v in values]
            found = [t for group in found if group for t in group]
            return found or None
        if isinstance(target, inference.ValueTarget):
            return None if isinstance(target.value, RuntimeValue) else [target]
        if not isinstance(target, scopes.Binding) \
                or target.form not in (scopes.IMPORT, scopes.IMPORT_FROM):
            return [target]
        if id(target) in seen:
            return None
        seen = seen | {id(target)}
        details = target.details
        analysis = target.home.tree.analysis
        project = self.project
        if target.form == scopes.IMPORT:
            module = project.module_value(details["module"], 0, analysis.path)
            if isinstance(module, (StaticModule, DirectoryModule)):
                return [inference.ValueTarget(module)]
            return None
        module = project.module_value(details["module"], details["level"], analysis.path)
        if not isinstance(module, (StaticModule, DirectoryModule)):
            return None
        attr = details["attr"]
        inner = [t for t in module.attribute_targets(attr) if t is not target]
        if isinstance(module, StaticModule) and not inner:
            sub = None
            package = module.analysis.package_dir()
            if package:
                sub = project.submodule_value(package, attr)
            inner = [inference.ValueTarget(sub)] if sub is not None else []
        result = []
        for item in inner:
            found = self._follow(item, seen)
            if found:
                result.extend(found)
        return result or None


class _ComprehensionTarget:
    def __init__(self, analysis, generator, target):
        self.analysis = analysis
        self.generator = generator
        self.target = target


class _Finder:
    """Walks the main file's syntax tree looking for the cursor's identifier."""

    def __init__(self, analysis, line, col):
        self.analysis = analysis
        self.tree = analysis.tree
        self.line = line
        self.col = col
        self.exact = None
        self.touching = None
        self.conditions = []
        self.comprehension = {}
        self.bindings = {}
        for binding in _all_bindings(self.tree.module):
            if binding.node is not None:
                self.bindings.setdefault(id(binding.node), binding)

    def find(self):
        module = self.tree.module
        for statement in module.node.body:
            self._walk(statement, module, None, {})
        return self.exact or self.touching

    def _check(self, line, start, name, make):
        if line != self.line or name is None:
            return
        end = start + len(name)
        if start <= self.col < end:
            if self.exact is None:
                self.exact = make()
        elif self.col == end and self.touching is None:
            self.touching = make()

    def _occurrence(self, kind, node, scope, stmt, **extra):
        conditions = list(self.conditions)
        comprehension = self.comprehension
        return lambda: _Occurrence(self.analysis, kind, node, scope, stmt, conditions,
                                   comprehension, **extra)

    def _walk_narrowed(self, node, scope, stmt, comprehension, conditions):
        saved = self.conditions
        self.conditions = saved + list(conditions)
        try:
            self._walk(node, scope, stmt, comprehension)
        finally:
            self.conditions = saved

    def _bound(self, node, scope, stmt, fallback_kind="name"):
        binding = self.bindings.get(id(node))
        if binding is not None:
            return self._occurrence("binding", node, scope, stmt, binding=binding)
        return self._occurrence(fallback_kind, node, scope, stmt)

    def _walk(self, node, scope, stmt, comprehension):
        if node is None or not self._within(node):
            return
        saved = self.comprehension
        self.comprehension = comprehension
        try:
            self._visit(node, scope, stmt, comprehension)
        finally:
            self.comprehension = saved

    def _visit(self, node, scope, stmt, comprehension):
        if isinstance(node, (ast.stmt, ast.ExceptHandler, ast.match_case)):
            stmt = node
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            self._function(node, scope, stmt)
        elif isinstance(node, ast.ClassDef):
            for child in node.decorator_list + node.bases:
                self._walk(child, scope, stmt, comprehension)
            for keyword in node.keywords:
                if keyword.arg is not None:
                    self._check(keyword.lineno, keyword.col_offset, keyword.arg,
                                self._occurrence("nothing", keyword, scope, stmt))
                self._walk(keyword.value, scope, stmt, comprehension)
            self._type_params(node, scope, stmt)
            line, col = self.tree.definition_position(node)
            self._check(line, col, node.name, self._bound(node, scope, stmt))
            inner = self.analysis.scope_of(node) or scope
            for child in node.body:
                self._walk(child, inner, child, {})
        elif isinstance(node, ast.Lambda):
            args = node.args
            for default in args.defaults + [d for d in args.kw_defaults if d is not None]:
                self._walk(default, scope, stmt, comprehension)
            for arg in _arguments(args):
                self._check(arg.lineno, arg.col_offset, arg.arg,
                            self._occurrence("lambda", arg, scope, stmt))
            shadowed = {k: v for k, v in comprehension.items()
                        if k not in {a.arg for a in _arguments(args)}}
            self._walk(node.body, scope, stmt, shadowed)
        elif isinstance(node, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):
            self._comprehension(node, scope, stmt, comprehension)
        elif isinstance(node, ast.BoolOp):
            known = []
            for value in node.values:
                self._walk_narrowed(value, scope, stmt, comprehension, known)
                positive, negative = flow.conditions(value)
                known = known + (positive if isinstance(node.op, ast.And) else negative)
        elif isinstance(node, ast.IfExp):
            positive, negative = flow.conditions(node.test)
            self._walk(node.test, scope, stmt, comprehension)
            self._walk_narrowed(node.body, scope, stmt, comprehension, positive)
            self._walk_narrowed(node.orelse, scope, stmt, comprehension, negative)
        elif isinstance(node, ast.Name):
            if node.id in comprehension:
                make = self._occurrence("comprehension", node, scope, stmt)
            elif isinstance(node.ctx, ast.Store):
                make = self._bound(node, scope, stmt)
            else:
                make = self._occurrence("name", node, scope, stmt)
            self._check(node.lineno, node.col_offset, node.id, make)
        elif isinstance(node, ast.Attribute):
            self._walk(node.value, scope, stmt, comprehension)
            binding = self.bindings.get(id(node)) if isinstance(node.ctx, ast.Store) else None
            if binding is not None:
                make = self._occurrence("binding", node, scope, stmt, binding=binding)
            else:
                make = self._occurrence("attr", node, scope, stmt)
            self._check(node.end_lineno, node.end_col_offset - len(node.attr), node.attr, make)
        elif isinstance(node, ast.Call):
            self._walk(node.func, scope, stmt, comprehension)
            for arg in node.args:
                self._walk(arg, scope, stmt, comprehension)
            for keyword in node.keywords:
                if keyword.arg is not None:
                    self._check(keyword.lineno, keyword.col_offset, keyword.arg,
                                self._occurrence("keyword", keyword, scope, stmt, call=node))
                self._walk(keyword.value, scope, stmt, comprehension)
        elif isinstance(node, ast.Import):
            self._import(node, scope, stmt)
        elif isinstance(node, ast.ImportFrom):
            self._import_from(node, scope, stmt)
        elif isinstance(node, ast.ExceptHandler):
            self._walk(node.type, scope, stmt, comprehension)
            binding = self.bindings.get(id(node))
            if binding is not None:
                line, col = binding.position
                self._check(line, col, node.name, self._bound(node, scope, stmt))
            for child in node.body:
                self._walk(child, scope, child, comprehension)
        elif isinstance(node, (ast.Global, ast.Nonlocal)):
            col = node.col_offset
            for name in node.names:
                line, col = self.tree.find_identifier(name, node.lineno, col)
                kind = "global" if isinstance(node, ast.Global) else "name"
                target = ast.Name(id=name, ctx=ast.Load())
                self._check(line, col, name,
                            self._occurrence(kind, target, scope, stmt, name=name))
        elif isinstance(node, (ast.MatchAs, ast.MatchStar, ast.MatchMapping)):
            for child in ast.iter_child_nodes(node):
                self._walk(child, scope, stmt, comprehension)
            binding = self.bindings.get(id(node))
            if binding is not None:
                line, col = binding.position
                self._check(line, col, binding.name, self._bound(node, scope, stmt))
        else:
            for child in ast.iter_child_nodes(node):
                self._walk(child, scope, stmt, comprehension)

    def _within(self, node):
        first = getattr(node, "lineno", None)
        if first is None:
            return True
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) \
                and node.decorator_list:
            first = min(first, min(d.lineno for d in node.decorator_list))
        last = getattr(node, "end_lineno", None) or first
        return first <= self.line <= last

    def _type_params(self, node, scope, stmt):
        for param in getattr(node, "type_params", None) or ():
            name = getattr(param, "name", None)
            if name:
                self._check(param.lineno, param.col_offset + _type_param_prefix(param), name,
                            self._occurrence("nothing", param, scope, stmt))

    def _function(self, node, scope, stmt):
        for child in node.decorator_list:
            self._walk(child, scope, stmt, {})
        self._type_params(node, scope, stmt)
        args = node.args
        for default in args.defaults + [d for d in args.kw_defaults if d is not None]:
            self._walk(default, scope, stmt, {})
        inner = self.analysis.scope_of(node) or scope
        for arg in _arguments(args):
            self._walk(arg.annotation, scope, stmt, {})
            self._check(arg.lineno, arg.col_offset, arg.arg, self._bound(arg, inner, stmt))
        self._walk(node.returns, scope, stmt, {})
        line, col = self.tree.definition_position(node)
        self._check(line, col, node.name, self._bound(node, scope, stmt))
        for child in node.body:
            self._walk(child, inner, child, {})

    def _comprehension(self, node, scope, stmt, comprehension):
        visible = dict(comprehension)
        for generator in node.generators:
            self._walk(generator.iter, scope, stmt, visible)
            before = dict(visible)
            for name_node, path in _target_names(generator.target):
                visible[name_node.id] = (generator, name_node, path, before)
            self._walk(generator.target, scope, stmt, visible)
            for condition in generator.ifs:
                self._walk(condition, scope, stmt, visible)
        if isinstance(node, ast.DictComp):
            self._walk(node.key, scope, stmt, visible)
            self._walk(node.value, scope, stmt, visible)
        else:
            self._walk(node.elt, scope, stmt, visible)

    def _import(self, node, scope, stmt):
        for alias in node.names:
            binding = self.bindings.get(id(alias))
            parts = alias.name.split(".")
            col = alias.col_offset
            for index, part in enumerate(parts):
                dotted = ".".join(parts[: index + 1])
                if index == 0 and not alias.asname and binding is not None:
                    make = self._occurrence("binding", alias, scope, stmt, binding=binding)
                else:
                    make = self._occurrence("module", alias, scope, stmt, dotted=dotted, level=0)
                self._check(alias.lineno, col, part, make)
                col += len(part) + 1
            if alias.asname and binding is not None:
                line, col = binding.position
                self._check(line, col, alias.asname,
                            self._occurrence("binding", alias, scope, stmt, binding=binding))

    def _import_from(self, node, scope, stmt):
        if node.module:
            line, col = _module_position(self.tree, node)
            parts = node.module.split(".")
            for index, part in enumerate(parts):
                dotted = ".".join(parts[: index + 1])
                self._check(line, col, part, self._occurrence(
                    "module", node, scope, stmt, dotted=dotted, level=node.level))
                col += len(part) + 1
        for alias in node.names:
            binding = self.bindings.get(id(alias))
            if binding is None:
                continue
            if alias.asname:
                self._check(alias.lineno, alias.col_offset, alias.name, self._occurrence(
                    "imported", alias, scope, stmt, import_binding=binding))
                line, col = binding.position
                self._check(line, col, alias.asname,
                            self._occurrence("binding", alias, scope, stmt, binding=binding))
            else:
                self._check(alias.lineno, alias.col_offset, alias.name,
                            self._occurrence("binding", alias, scope, stmt, binding=binding))


def _type_param_prefix(param):
    """Width of the ``*``/``**`` before a type parameter's name."""
    if param.__class__.__name__ == "TypeVarTuple":
        return 1
    if param.__class__.__name__ == "ParamSpec":
        return 2
    return 0


def _module_position(tree, node):
    """Position of the module name in ``from <module> import ...``."""
    for number in range(node.lineno, (node.end_lineno or node.lineno) + 1):
        text = tree.line_text(number)
        start = node.col_offset if number == node.lineno else 0
        match = re.compile(r"\bfrom\s*\.*\s*").search(text, start)
        if match:
            return number, match.end()
    return node.lineno, node.col_offset


def _arguments(args):
    found = args.posonlyargs + args.args
    if args.vararg:
        found.append(args.vararg)
    found += args.kwonlyargs
    if args.kwarg:
        found.append(args.kwarg)
    return found


def _target_names(target, path=()):
    if isinstance(target, ast.Name):
        yield target, path
    elif isinstance(target, (ast.Tuple, ast.List)):
        for index, element in enumerate(target.elts):
            if isinstance(element, ast.Starred):
                for name, _ in _target_names(element.value):
                    yield name, None
            else:
                yield from _target_names(element, path + (index,))


def _all_bindings(scope):
    yield from scope.events
    yield from scope.instance_events
    for child in scope.children:
        yield from _all_bindings(child)


# ---------------------------------------------------------------------------
# Describing definitions

class _Describer:
    def __init__(self, project):
        self.project = project
        self.root = project.root

    # -- entry points ----------------------------------------------------
    def targets(self, targets):
        records = []
        for target in targets:
            if isinstance(target, scopes.Binding):
                records.append(self.binding(target))
            elif isinstance(target, inference.BindingEntity):
                records.append(self.binding(target.binding))
            elif isinstance(target, inference.AttributeEntity):
                records.extend(self.binding(b) for b in target.bindings)
            elif isinstance(target, RuntimeEntity):
                records.append(self.runtime_entity(target))
            elif isinstance(target, inference.ValueEntity):
                records.extend(self.value(v) for v in target.values())
            elif isinstance(target, inference.ValueTarget):
                records.append(self.value(target.value))
            elif isinstance(target, _ComprehensionTarget):
                records.append(self.comprehension(target))
        return records

    def values(self, values):
        return [self.value(value) for value in values]

    # -- helpers ---------------------------------------------------------
    def relative(self, path):
        if not path:
            return ""
        path = os.path.abspath(path)
        try:
            relative = os.path.relpath(path, self.root)
        except ValueError:  # another drive (Windows)
            relative = path
        if relative.startswith(os.pardir + os.sep) or relative == os.pardir:
            relative = path
        return relative.replace(os.sep, "/")

    def module_name(self, path):
        relative = self.relative(path)
        if os.path.isabs(relative):
            relative = os.path.basename(relative)
        if relative.endswith(".py"):
            relative = relative[:-3]
        parts = [p for p in relative.split("/") if p]
        if len(parts) > 1 and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def directory_name(self, directory):
        return ".".join(p for p in self.relative(directory).split("/") if p)

    def relative_import_name(self, importer, dotted, level):
        """Qualified name of ``<level dots><dotted>`` imported from ``importer``."""
        if not level:
            return dotted
        parts = self.module_name(importer).split(".")
        drop = level - 1 if os.path.basename(importer) == "__init__.py" else level
        parts = parts[: max(0, len(parts) - drop)] if drop <= len(parts) else []
        return ".".join(p for p in parts + [dotted] if p)

    def qualified(self, scope, name=None):
        names = []
        while scope is not None and scope.parent is not None:
            names.append(scope.name)
            scope = scope.parent
        tree = scope.tree if scope is not None else None
        prefix = [self.module_name(tree.path)] if tree is not None and tree.path else []
        result = prefix + list(reversed(names))
        if name is not None:
            result.append(name)
        return ".".join(p for p in result if p)

    @staticmethod
    def record(name, kind, full_name, module_path, line, column, description, docstring):
        return {"name": name, "type": kind, "full_name": full_name,
                "module_path": module_path, "line": line, "column": column,
                "description": description, "docstring": docstring or ""}

    # -- source definitions ----------------------------------------------
    def binding(self, binding):
        form = binding.form
        tree = binding.home.tree
        line, column = binding.position
        module_path = self.relative(tree.path)
        if form in (scopes.DEF, scopes.CLASS):
            scope = tree.analysis.scope_of(binding.node)
            if scope is not None:
                return self.scope_definition(scope)
        owner = binding.details.get("owner")
        if owner is not None:
            full_name = self.qualified(owner, binding.name)
        else:
            full_name = self.qualified(binding.scope, binding.name)
        if form == scopes.PARAM:
            return self.record(binding.name, "param", full_name, module_path, line, column,
                               "param %s" % binding.name, "")
        if form in (scopes.IMPORT, scopes.IMPORT_FROM):
            return self.import_binding(binding, module_path, line, column)
        return self.record(binding.name, "statement", full_name, module_path, line, column,
                           _statement_description(tree, binding), "")

    def import_binding(self, binding, module_path, line, column):
        analysis = binding.home.tree.analysis
        details = binding.details
        values = analysis.binding_values(binding)
        kind = "module"
        full_name = None
        if binding.form == scopes.IMPORT:
            full_name = details["module"]
        else:
            for value in values:
                if value.kind in (inference.MODULE, inference.CLASS, inference.FUNCTION,
                                  inference.INSTANCE):
                    kind = value.kind
                    break
            module = analysis.project.module_value(details["module"], details["level"],
                                                   analysis.path)
            prefix = None
            if isinstance(module, StaticModule):
                prefix = self.module_name(module.analysis.path)
            elif isinstance(module, DirectoryModule):
                prefix = self.directory_name(module.directory)
            elif isinstance(module, RuntimeValue):
                prefix = getattr(module.obj, "__name__", None)
            if not prefix:
                prefix = self.relative_import_name(analysis.path, details["module"] or "",
                                                   details["level"])
            full_name = "%s.%s" % (prefix, details["attr"]) if prefix else details["attr"]
        description = _import_text(binding.home.tree, binding.stmt)
        return self.record(binding.name, kind, full_name, module_path, line, column,
                           description, "")

    def scope_definition(self, scope, instance=False):
