"""Completion engine.

Secret: the completion policy — which candidates each cursor context offers
(visible names plus keywords, or public module members, or the attributes
of every possible receiver value, or importable modules, or the names a
module exports to ``from ... import``) and how filtering, wording and
ranking are combined.
"""

from . import cursor, matching, presentation, ranking, vocabulary
from .inference import MODULE, Project
from .source import SourceFile


def complete(path, line, col, fuzzy=False, root=None):
    """Return completions as a list of (name, complete, type, description)."""
    source = SourceFile(path)
    source.check_position(line, col)
    context = cursor.analyze(source.text_before(line, col))
    if context.kind == cursor.NONE:
        return []

    text = source.lines()[line - 1]
    indent = len(text) - len(text.lstrip()) if text[:col].strip() else col
    project = Project(source.path, source.text(), root)
    keywords = []
    if context.kind == cursor.IMPORT_MODULE:
        entities = project.module_names(context.module, context.level)
    elif context.kind == cursor.IMPORT_NAME:
        module = project.module_value(context.module, context.level)
        entities = project.importable_members(module) if module is not None else {}
    elif context.kind == cursor.KEYWORDS:
        entities = {}
        keywords = context.words
    elif context.kind == cursor.NAME:
        entities = project.location(line, col, indent).visible_entities()
        keywords = vocabulary.keywords()
    else:
        entities = {}
        for receiver in project.location(line, col, indent).evaluate(context.receiver):
            members = receiver.members()
            if receiver.kind == MODULE:
                members = dict(project.submodule_entities(receiver), **members)
            for name, entity in members.items():
                if receiver.kind == MODULE and name.startswith("_"):
                    continue
                entities.setdefault(name, entity)

    query = context.prefix
    results = []
    for name, entity in entities.items():
        if matching.matches(name, query, fuzzy):
            kind, type_name = entity.presentation()
            results.append((name, False) + presentation.describe(name, kind, type_name))
    for word in keywords:
        if word not in entities and matching.matches(word, query, fuzzy):
            results.append((word, True) + presentation.describe(word, presentation.KEYWORD))

    ordered = ranking.rank(results, name_of=lambda r: r[0], is_keyword=lambda r: r[1])
    return [(name, matching.remaining_text(name, query), kind, description)
            for name, _, kind, description in ordered]
"""Result serialization.

Secret: the wire format of the result (compact JSON with a ``completions``
array of name/complete/type/description objects, or a ``definitions`` array
of definition objects, newline-terminated).
"""

import json
import sys


_DEFINITION_FIELDS = ("name", "type", "full_name", "module_path", "line", "column",
                      "description", "docstring")


def write_completions(completions, stream=None):
    """``completions``: iterable of (name, complete, type, description)."""
    payload = {"completions": [
        {"name": name, "complete": complete, "type": kind, "description": description}
        for name, complete, kind, description in completions
    ]}
    _write(payload, stream)


def write_definitions(definitions, stream=None):
    """``definitions``: iterable of dicts with the definition fields."""
    payload = {"definitions": [{field: d[field] for field in _DEFINITION_FIELDS}
                               for d in definitions]}
    _write(payload, stream)


def _write(payload, stream):
    text = json.dumps(payload, separators=(",", ":"), ensure_ascii=False) + "\n"
    stream = stream or sys.stdout
    if hasattr(stream, "buffer"):
        stream.flush()
        stream.buffer.write(text.encode("utf-8"))
        stream.buffer.flush()
    else:
        stream.write(text)
        stream.flush()
"""Source file access.

Secret: how a file on disk is read, decoded and split into lines, and how a
(1-based line, 0-based column) cursor is validated against it.
"""

import os


class SourceError(Exception):
    """The file cannot be used as input (missing, undecodable, bad cursor)."""


class SourceFile:
    def __init__(self, path):
        if not os.path.isfile(path):
            raise SourceError("not a regular file: %s" % path)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except OSError as exc:
            raise SourceError("cannot read %s: %s" % (path, exc))
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise SourceError("file is not valid UTF-8: %s" % path)
        if text.startswith("\ufeff"):
            text = text[1:]
        text = text.replace("\r\n", "\n").replace("\r", "\n")
        self._path = os.path.abspath(path)
        self._lines = text.split("\n")

    @property
    def path(self):
        return self._path

    def text(self):
        return "\n".join(self._lines)

    def lines(self):
        """The file's lines without line terminators (a copy)."""
        return list(self._lines)

    def check_position(self, line, col):
        if line < 1 or line > len(self._lines):
            raise SourceError("line %d out of range" % line)
        if col < 0 or col > len(self._lines[line - 1]):
            raise SourceError("column %d out of range" % col)

    def text_before(self, line, col):
        """All text from the start of the file up to the cursor."""
        head = self._lines[: line - 1]
        head.append(self._lines[line - 1][:col])
        return "\n".join(head)
"""Completion wording.

Secret: the vocabulary used for a completion's ``type`` field and the
format of its human-readable ``description``.
"""

KEYWORD = "keyword"


def describe(name, kind, type_name=None):
    """Return ``(type, description)`` for a name of the given kind."""
    if kind == "module":
        return "module", "module %s" % name
    if kind == "class":
        return "class", "class %s" % name
    if kind == "function":
        return "function", "def %s(...)" % name
    if kind == "instance":
        return "instance", "instance of %s" % (type_name or "object")
    if kind == "param":
        return "param", "param %s" % name
    if kind == KEYWORD:
        return "keyword", name
    return "statement", "statement"
"""Completion ordering.

Secret: the ranking rules — public names, then private, then dunder names,
then keywords, each group alphabetical ignoring case.
"""


def _group(name, is_keyword):
    if is_keyword:
        return 3
    if name.startswith("__") and name.endswith("__"):
        return 2
    if name.startswith("_"):
        return 1
    return 0


def rank(items, name_of, is_keyword):
    """Return ``items`` sorted; ``name_of``/``is_keyword`` describe an item."""
    return sorted(items, key=lambda item: (_group(name_of(item), is_keyword(item)),
                                           name_of(item).lower(), name_of(item)))
"""Query matching.

Secret: the algorithm deciding whether a typed query matches a candidate
name (case-insensitive prefix, or case-insensitive in-order subsequence when
fuzzy) and how much of the name remains to be inserted.
"""


def matches(name, query, fuzzy=False):
    if not query:
        return True
    name, query = name.lower(), query.lower()
    if not fuzzy:
        return name.startswith(query)
    position = 0
    for ch in query:
        position = name.find(ch, position)
        if position < 0:
            return False
        position += 1
    return True


def remaining_text(name, query):
    """Text to insert: the name minus as many characters as were typed."""
    return name[len(query):]
"""Language vocabulary.

Secret: where the builtin namespace and the keyword list come from (here:
the running interpreter's ``builtins`` and ``keyword`` modules).
"""

import builtins
import keyword


def keywords():
    return list(keyword.kwlist)


def builtin_namespace():
    """The object whose attributes are the builtin names."""
    return builtins


def builtin_names():
    """Builtin names, excluding those that are reserved keywords."""
    reserved = set(keyword.kwlist)
    return [name for name in dir(builtins) if name not in reserved]
"""Runtime object introspection.

Secret: how a live Python object is classified (module, class, function or
instance) and how its attributes are enumerated and fetched safely.
"""

import inspect

MODULE = "module"
CLASS = "class"
FUNCTION = "function"
INSTANCE = "instance"


def kind_of(obj):
    if inspect.ismodule(obj):
        return MODULE
    if isinstance(obj, type):
        return CLASS
    if inspect.isroutine(obj):
        return FUNCTION
    return INSTANCE


def type_name(obj):
    """Name of the type of ``obj`` (for describing instances)."""
    return type(obj).__name__


def class_name(cls):
    return getattr(cls, "__name__", type(cls).__name__)


def attribute_names(obj):
    try:
        return [n for n in dir(obj) if isinstance(n, str)]
    except Exception:
        return []


def get_attribute(obj, name):
    """Return ``(True, value)`` or ``(False, None)`` if fetching fails."""
    try:
        return True, getattr(obj, name)
    except BaseException:  # noqa: B902 - descriptors may raise anything
        return False, None


def is_data_descriptor(obj):
    return inspect.isdatadescriptor(obj)


_SAFE_SAMPLE_MODULES = ("builtins",)


def sample_instance(cls):
    """An instance of ``cls`` built without side effects, or None."""
    if getattr(cls, "__module__", None) not in _SAFE_SAMPLE_MODULES:
        return None
    try:
        return cls()
    except BaseException:  # noqa: B902 - constructors may raise anything
        return None
"""Error-tolerant parsing.

Secret: the repair strategy used to turn syntactically broken source into a
syntax tree. Lines keep their numbers, so positions in the returned tree
match positions in the original text.
"""

import ast
import keyword
import re

_ORIGINAL, _PASSED, _BLANKED = 0, 1, 2
_HEADER_RE = re.compile(r"on line (\d+)")
_DEF_RE = re.compile(r"^(\s*)(async\s+)?def\s+([^\W\d]\w*)")
_CLASS_RE = re.compile(r"^(\s*)class\s+([^\W\d]\w*)")
_PARAM_RE = re.compile(r"\s*\*{0,2}\s*([^\W\d]\w*)")
_SALVAGED = 3


def parse_tolerant(text):
    """Return an ``ast.Module`` for ``text``, repairing errors as needed."""
    lines = text.replace("\0", " ").split("\n")
    state = [_ORIGINAL] * len(lines)
    patched_headers = set()
    for _ in range(4 * len(lines) + 20):
        try:
            return ast.parse("\n".join(lines))
        except SyntaxError as exc:
            if not _repair(lines, state, patched_headers, exc):
                break
        except (ValueError, RecursionError, MemoryError):
            break
    return ast.Module(body=[], type_ignores=[])


def _repair(lines, state, patched_headers, exc):
    msg = exc.msg or ""
    if msg.startswith("expected an indented block"):
        match = _HEADER_RE.search(msg)
        if match:
            header = int(match.group(1)) - 1
            if 0 <= header < len(lines) and header not in patched_headers:
                patched_headers.add(header)
                lines[header] = _with_pass_body(lines[header])
                return True
    idx = (exc.lineno or len(lines)) - 1
    idx = max(0, min(idx, len(lines) - 1))
    if msg.startswith("unterminated triple-quoted string") and ("eof", idx) not in patched_headers:
        patched_headers.add(("eof", idx))
        text = lines[idx][max(0, (exc.offset or 1) - 1):]
        quotes = [q for q in ('"""', "'''") if q in text]
        if quotes:
            lines[-1] += min(quotes, key=text.index)
            return True
    while idx >= 0 and (state[idx] == _BLANKED or not lines[idx].strip()):
        idx -= 1
    if idx < 0:
        return False
    if msg.startswith("expected 'except' or 'finally' block"):
        header = _find_try_header(lines, idx)
        if header is not None:
            lines[header] = lines[header][: _indent_width(lines[header])] + "if True:"
            return True
    if msg.startswith("unexpected indent"):
        _blank_block(lines, state, idx)
        return True
    if state[idx] == _ORIGINAL and lines[idx].rstrip().endswith(":"):
        salvaged = _salvage_header(lines[idx])
        if salvaged is not None and salvaged != lines[idx]:
            state[idx] = _SALVAGED
            lines[idx] = salvaged
            return True
    if state[idx] in (_ORIGINAL, _SALVAGED):
        stripped = lines[idx].lstrip()
        indent = lines[idx][: len(lines[idx]) - len(stripped)]
        state[idx] = _PASSED
        lines[idx] = indent + "pass"
    else:
        state[idx] = _BLANKED
        lines[idx] = ""
    return True


def _blank_block(lines, state, idx):
    """Blank an orphaned indented block: line ``idx`` and deeper/equal lines after it."""
    width = _indent_width(lines[idx])
    end = idx
    while end < len(lines) and (not lines[end].strip() or _indent_width(lines[end]) >= width):
        if lines[end].strip():
            state[end] = _BLANKED
            lines[end] = ""
        end += 1


def _find_try_header(lines, idx):
    """The ``try:`` line whose handlers are missing at line ``idx``."""
    limit = _indent_width(lines[idx]) if lines[idx].strip() else None
    for number in range(min(idx, len(lines) - 1), -1, -1):
        stripped = lines[number].strip()
        if not stripped:
            continue
        width = _indent_width(lines[number])
        if stripped.replace(" ", "") == "try:" and (limit is None or width <= limit):
            return number
        if limit is not None and width < limit:
            return None
    return None


def _indent_width(line):
    return len(line) - len(line.lstrip())


def _salvage_header(line):
    """Reduce a broken ``def``/``class`` header to a minimal valid one."""
    match = _DEF_RE.match(line)
    if match:
        params = []
        rest = line[match.end():]
        if rest.lstrip().startswith("("):
            inside = rest[rest.index("(") + 1: rest.rfind(":")]
            for piece in inside.split(","):
                found = _PARAM_RE.match(piece)
                if found and found.group(1) not in params \
                        and not keyword.iskeyword(found.group(1)):
                    params.append(found.group(1))
        return "%s%sdef %s(%s):" % (match.group(1), match.group(2) or "", match.group(3),
                                    ", ".join(params))
    match = _CLASS_RE.match(line)
    if match:
        return "%sclass %s:" % (match.group(1), match.group(2))
    return None


def _with_pass_body(line):
    """Give a block header such as ``if x:`` an inline ``pass`` body."""
    stripped = line.rstrip()
    if stripped.endswith(":"):
        return stripped + " pass"
    colon = stripped.rfind(":")
    if colon >= 0:
        return stripped[: colon + 1] + " pass"
    return stripped

"""Module location.

Secret: how an imported module name is found — first as a source file or
package in the project directory, otherwise by importing a standard library
module at runtime (with its side effects contained) — and how the module
names importable from a place are enumerated.
"""

import contextlib
import importlib
import io
import os
import pkgutil
import sys
import sysconfig

SOURCE = "source"
RUNTIME = "runtime"
DIRECTORY = "directory"


class Located:
    """Where a module lives: a source file, a bare directory, or a live module."""

    def __init__(self, how, path=None, module=None):
        self.how = how
        self.path = path
        self.module = module


class ModuleLocator:
    def __init__(self, project_dir):
        self._project_dir = os.path.abspath(project_dir)
        self._runtime_cache = {}

    def locate(self, dotted, level=0, importer_path=None):
        """Locate ``dotted`` (relative to ``importer_path`` when ``level`` > 0)."""
        parts = [p for p in dotted.split(".") if p] if dotted else []
        if level > 0:
            base = self.relative_base(level, importer_path)
            return self._locate_in(base, parts) if base is not None else None
        if not parts:
            return None
        namespace = None
        for root in self.search_roots(importer_path):
            found = self._locate_in(root, parts)
            if found is not None and found.how == SOURCE:
                return found
            namespace = namespace or found
        if namespace is not None and _holds_python(namespace.path):
            return namespace
        module = self._import_runtime(".".join(parts))
        if module is not None:
            return Located(RUNTIME, module=module)
        return namespace

    def relative_base(self, level, importer_path):
        """Directory a relative import of ``level`` dots starts from, or None
        when it would leave the project."""
        base = os.path.dirname(os.path.abspath(importer_path or self._project_dir))
        for _ in range(level - 1):
            base = os.path.dirname(base)
        if base != self._project_dir and not base.startswith(
                self._project_dir.rstrip(os.sep) + os.sep):
            return None
        return base

    def search_roots(self, importer_path=None):
        roots = [self._project_dir]
        if importer_path:
            own = os.path.dirname(os.path.abspath(importer_path))
            if own not in roots:
                roots.append(own)
        return roots

    def top_level_names(self, importer_path=None):
        """Names of the modules ``import <name>`` can find."""
        names = set()
        for root in self.search_roots(importer_path):
            names.update(directory_module_names(root))
        names.update(stdlib_names())
        return names

    def locate_in_directory(self, directory, name):
        """Locate submodule ``name`` of the package stored in ``directory``."""
        return self._locate_in(directory, [name])

    def _locate_in(self, base, parts):
        path = base
        for index, part in enumerate(parts):
            last = index == len(parts) - 1
            package = os.path.join(path, part)
            regular = os.path.isfile(os.path.join(package, "__init__.py"))
            if os.path.isdir(package) and (regular or not os.path.isfile(package + ".py")):
                if last:
                    return self._package(package)
                path = package
                continue
            if last and os.path.isfile(package + ".py"):
                return Located(SOURCE, path=package + ".py")
            return None
        return self._package(path)

    @staticmethod
    def _package(directory):
        init = os.path.join(directory, "__init__.py")
        if os.path.isfile(init):
            return Located(SOURCE, path=init)
        return Located(DIRECTORY, path=directory)

    def _import_runtime(self, name):
        if name in self._runtime_cache:
            return self._runtime_cache[name]
        if not _is_stdlib(name):
            self._runtime_cache[name] = None
            return None
        module = None
        saved_path = list(sys.path)
        sys.path[:] = [p for p in sys.path
                       if p and os.path.abspath(p) not in (self._project_dir, _TOOL_DIR)]
        try:
            with _silenced_descriptors(), contextlib.redirect_stdout(io.StringIO()), \
                    contextlib.redirect_stderr(io.StringIO()):
                module = importlib.import_module(name)
        except BaseException:  # noqa: B902 - arbitrary import code may do anything
            module = None
        finally:
            sys.path[:] = saved_path
        self._runtime_cache[name] = module
        return module


@contextlib.contextmanager
def _silenced_descriptors():
    """Route OS-level stdout/stderr to the null device (for C extensions)."""
    saved = []
    try:
        sys.stdout.flush()
        sys.stderr.flush()
        devnull = os.open(os.devnull, os.O_WRONLY)
        for fd in (1, 2):
            saved.append((fd, os.dup(fd)))
            os.dup2(devnull, fd)
        os.close(devnull)
    except (OSError, ValueError, AttributeError):
        pass
    try:
        yield
    finally:
        for fd, copy in saved:
            os.dup2(copy, fd)
            os.close(copy)


_TOOL_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Standard library modules never imported for analysis (they act on import).
_UNSAFE = ("antigravity", "this", "__main__", "idlelib.idle", "idlelib.__main__")


def _is_stdlib(name):
    if name in _UNSAFE or name.endswith(".__main__"):
        return False
    top = name.split(".")[0]
    return top in getattr(sys, "stdlib_module_names", ()) or top in sys.builtin_module_names


_STDLIB_NAMES = None


def stdlib_names():
    """Top-level standard library modules available in this runtime."""
    global _STDLIB_NAMES
    if _STDLIB_NAMES is None:
        known = set(getattr(sys, "stdlib_module_names", ())) | set(sys.builtin_module_names)
        found = set(sys.builtin_module_names)
        directories = []
        for key in ("stdlib", "platstdlib"):
            path = sysconfig.get_paths().get(key)
            if path:
                directories += [path, os.path.join(path, "lib-dynload")]
        directories += [os.path.dirname(os.__file__)]
        directories = [d for d in dict.fromkeys(directories) if os.path.isdir(d)]
        try:
            found.update(info.name for info in pkgutil.iter_modules(directories))
        except (OSError, ImportError):
            pass
        _STDLIB_NAMES = {n for n in found & known if n not in _UNSAFE}
    return set(_STDLIB_NAMES)


def _holds_python(directory, depth=3):
    """Whether a namespace directory contains Python sources (near the top)."""
    try:
        entries = os.listdir(directory)
    except OSError:
        return False
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            return True
        if depth > 1 and entry.isidentifier() and os.path.isdir(path) \
                and _holds_python(path, depth - 1):
            return True
    return False


def directory_module_names(directory):
    """Modules and packages (regular or namespace) stored directly in ``directory``."""
    names = set()
    try:
        entries = os.listdir(directory)
    except OSError:
        return names
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            name = entry[:-3]
        elif os.path.isdir(path):
            name = entry
        else:
            continue
        if name.isidentifier() and name not in ("__init__", "__pycache__", "__main__"):
            names.add(name)
    return names


def runtime_submodule_names(module):
    """Submodules of a live package."""
    path = getattr(module, "__path__", None)
    if not path:
        return set()
    try:
        return {info.name for info in pkgutil.iter_modules(list(path))
                if info.name.isidentifier() and info.name != "__main__"}
    except (OSError, ImportError, TypeError):
        return set()
"""Scope and binding model.

Secret: how name bindings are discovered in a syntax tree, which scope they
belong to, and the rules (indentation heuristics included) that decide which
scope encloses a cursor and which bindings are visible from it.
"""

import ast
import re

from . import parsing

# Binding forms exposed to clients.
DEF = "def"
CLASS = "class"
PARAM = "param"
ASSIGN = "assign"
IMPORT = "import"
IMPORT_FROM = "import_from"
STAR = "star"
EXCEPT = "except"
OTHER = "other"


class Binding:
    """One event that binds a name (or, for STAR, a set of names)."""

    def __init__(self, name, form, line, order, scope, node=None, position=None,
                 stmt=None, home=None, **details):
        self.name = name
        self.form = form
        self.line = line
        self.order = order
        self.scope = scope
        # where the bound identifier itself is written: (1-based line, 0-based column)
        self.position = position or (line, 0)
        # the syntax node naming the binding, the statement (or handler/case)
        # that performs it, and the scope whose code contains that statement
        self.node = node
        self.stmt = stmt
        self.home = home or scope
        # form-specific details:
        #   DEF/CLASS: node
        #   PARAM: function (Scope), index, annotation, default, star ("", "*", "**"),
        #          keyword_only (optional)
        #   ASSIGN: value (expr or None), path (tuple of ints), annotation,
        #           owner (class Scope, for instance attributes), starred
        #   OTHER: source ("for"/"with"/None), value (iterable/context expr), path
        #   IMPORT: module (dotted name bound), as_name (bool)
        #   IMPORT_FROM: module, level, attr
        #   STAR: module, level
        #   EXCEPT: type_expr
        self.details = details


class Scope:
    MODULE, FUNCTION, CLASS = "module", "function", "class"

    def __init__(self, kind, node, parent, tree):
        self.kind = kind
        self.node = node
        self.parent = parent
        self.tree = tree
        self.children = []
        self.events = []
        self.instance_events = []  # self.<attr> assignments in methods (classes)
        self.globals_declared = set()

    @property
    def name(self):
        return getattr(self.node, "name", None)

    def class_scope(self):
        """For a method, the scope of the class that defines it."""
        if self.kind == Scope.FUNCTION and self.parent is not None \
                and self.parent.kind == Scope.CLASS:
            return self.parent
        return None

    def decorator_names(self):
        names = []
        for deco in getattr(self.node, "decorator_list", []):
            if isinstance(deco, ast.Name):
                names.append(deco.id)
            elif isinstance(deco, ast.Attribute):
                names.append(deco.attr)
        return names

    def returned_expressions(self):
        """Return-value expressions of a function (excluding nested scopes)."""
        found = []
        for node in _walk_own(self.node.body if self.node is not None else []):
            if isinstance(node, (ast.Yield, ast.YieldFrom)):
                return []
            if isinstance(node, ast.Return) and node.value is not None:
                found.append(node.value)
        return found

    def return_statements(self):
        """``return`` statements of a function, or None for generators."""
        found = []
        for node in _walk_own(self.node.body if self.node is not None else []):
            if isinstance(node, (ast.Yield, ast.YieldFrom)):
                return None
            if isinstance(node, ast.Return):
                found.append(node)
        return found

    def base_expressions(self):
        return list(getattr(self.node, "bases", []))

    def is_async(self):
        return isinstance(self.node, ast.AsyncFunctionDef)

    def chain(self):
        """Scopes searched for names from here: self, enclosing functions, module."""
        result = [self]
        scope = self.parent
        while scope is not None:
            if scope.kind != Scope.CLASS:
                result.append(scope)
            scope = scope.parent
        return result

    def events_until_line(self, line):
        return [e for e in self.events if e.line <= line]

    def events_before(self, order):
        return [e for e in self.events if e.order < order]

    def all_events(self):
        return list(self.events)

    def instance_attribute_events(self):
        return list(self.instance_events)


class ScopeTree:
    def __init__(self, text, path=None):
        self.path = path
        self._lines = text.split("\n")
        module = parsing.parse_tolerant(text)
        self.module = Scope(Scope.MODULE, module, None, self)
        _Collector(self.module).visit_body(module.body)

    def line_text(self, line):
        return self._lines[line - 1] if 0 < line <= len(self._lines) else ""

    def segment(self, node):
        """Source text of ``node`` (as written), or None."""
        try:
            first, last = node.lineno, node.end_lineno
            if last is None or first > len(self._lines):
                return None
            if first == last:
                return self._lines[first - 1][node.col_offset:node.end_col_offset]
            parts = [self._lines[first - 1][node.col_offset:]]
            parts.extend(self._lines[first:last - 1])
            parts.append(self._lines[last - 1][:node.end_col_offset])
            return "\n".join(parts)
        except (AttributeError, IndexError, TypeError):
            return None

    def find_identifier(self, name, line, col, after_keyword=None):
        """Position of identifier ``name`` at or after (line, col).

        With ``after_keyword`` the identifier must follow that keyword.
        """
        pattern = re.compile((r"\b%s\s+" % after_keyword if after_keyword else r"(?<![\w.])")
                             + r"(%s)\b" % re.escape(name))
        for number in range(line, min(line + 50, len(self._lines)) + 1):
            text = self._lines[number - 1]
            start = col if number == line else 0
            match = pattern.search(text, start)
            if match:
                return number, match.start(1)
        return line, col

    def definition_position(self, node):
        """Position of the name in a ``def``/``class`` header."""
        keyword = "class" if isinstance(node, ast.ClassDef) else "def"
        return self.find_identifier(node.name, node.lineno, node.col_offset, keyword)

    def scope_at(self, line, col):
        scope = self.module
        while True:
            inner = None
            for child in scope.children:
                if self._contains(child, line, col):
                    inner = child
            if inner is None:
                return scope
            scope = inner

    def _contains(self, scope, line, col):
        node = scope.node
        header, end = node.lineno, node.end_lineno or node.lineno
        header_col = node.col_offset
        body = node.body[0] if node.body else None
        if line < header:
            return False
        if line == header:
            return body is not None and body.lineno == header and col >= body.col_offset
        text = self._lines[line - 1] if line - 1 < len(self._lines) else ""
        before = text[:col]
        indent = _indent_width(text) if before.strip() else col
        if indent <= header_col and (line > end or not before.strip()):
            return False
        if line <= end:
            return True
        for number in range(end + 1, line):
            other = self._lines[number - 1] if number - 1 < len(self._lines) else ""
            stripped = other.strip()
            if stripped and not stripped.startswith("#") and _indent_width(other) <= header_col:
                return False
        return True


def _indent_width(text):
    return len(text) - len(text.lstrip())


def _walk_own(statements):
    """Walk nodes in ``statements`` without entering nested scopes."""
    stack = list(reversed(statements))
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(node))))


class _Counter:
    value = 0

    @classmethod
    def next(cls):
        cls.value += 1
        return cls.value


class _Collector(ast.NodeVisitor):
    def __init__(self, scope):
        self.scope = scope
        self.stmt = None

    def visit(self, node):
        if isinstance(node, (ast.stmt, ast.ExceptHandler, ast.match_case)):
            saved, self.stmt = self.stmt, node
            try:
                return super().visit(node)
            finally:
                self.stmt = saved
        return super().visit(node)

    # -- helpers ---------------------------------------------------------
    def visit_body(self, statements):
        for statement in statements:
            self.visit(statement)

    def _target_scope(self, name):
        if name in self.scope.globals_declared:
            scope = self.scope
            while scope.parent is not None:
                scope = scope.parent
            return scope
        return self.scope

    def bind(self, name, form, line, node=None, position=None, **details):
        scope = self._target_scope(name) if name else self.scope
        binding = Binding(name, form, line, _Counter.next(), scope, node=node,
                          position=position, stmt=self.stmt, home=self.scope, **details)
        scope.events.append(binding)
        return binding

    def bind_target(self, target, line, value, path=(), annotation=None, starred=False):
        if isinstance(target, ast.Name):
            self.bind(target.id, ASSIGN, line, node=target, position=_start(target),
                      value=value, path=path, annotation=annotation, starred=starred)
        elif isinstance(target, (ast.Tuple, ast.List)):
            for index, element in enumerate(target.elts):
                self.bind_target(element, line, value, path + (index,))
        elif isinstance(target, ast.Starred):
            self.bind_target(target.value, line, None, starred=True)
        else:
            self.visit(target)

    def bind_plain(self, target, line, source=None, value=None, path=()):
        if isinstance(target, ast.Name):
            self.bind(target.id, OTHER, line, node=target, position=_start(target),
                      source=source, value=value, path=path)
        elif isinstance(target, (ast.Tuple, ast.List)):
            for index, element in enumerate(target.elts):
                self.bind_plain(element, line, source, value, path + (index,))
        elif isinstance(target, ast.Starred):
            self.bind_plain(target.value, line)
        else:
            for node in ast.walk(target):
                if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                    self.bind(node.id, OTHER, line, node=node, position=_start(node))

    # -- scopes ----------------------------------------------------------
    def _visit_function(self, node):
        for deco in node.decorator_list:
            self.visit(deco)
        args = node.args
        for default in args.defaults + [d for d in args.kw_defaults if d is not None]:
            self.visit(default)
        tree = self.scope.tree
        self.bind(node.name, DEF, node.lineno, node=node,
                  position=tree.definition_position(node))
        child = Scope(Scope.FUNCTION, node, self.scope, tree)
        self.scope.children.append(child)
        positional = args.posonlyargs + args.args
        defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
        index = 0
        for arg, default in zip(positional, defaults):
            child_bind(child, arg, node, function=child, index=index,
                       annotation=arg.annotation, default=default, star="")
            index += 1
        if args.vararg:
            child_bind(child, args.vararg, node, function=child, index=index,
                       annotation=None, default=None, star="*")
            index += 1
        for arg, default in zip(args.kwonlyargs, args.kw_defaults):
            child_bind(child, arg, node, function=child, index=index,
                       annotation=arg.annotation, default=default, star="", keyword_only=True)
            index += 1
        if args.kwarg:
            child_bind(child, args.kwarg, node, function=child, index=index,
                       annotation=None, default=None, star="**")
        collector = _Collector(child)
        for statement in _walk_own(node.body):
            if isinstance(statement, ast.Global):
                child.globals_declared.update(statement.names)
        collector.visit_body(node.body)
        parent_class = child.class_scope()
        if parent_class is not None and positional:
            decorators = child.decorator_names()
            if "staticmethod" not in decorators and "classmethod" not in decorators:
                self_name = positional[0].arg
                _collect_instance_attributes(parent_class, child, node.body, self_name,
                                             initializer=node.name == "__init__")

    visit_FunctionDef = _visit_function
    visit_AsyncFunctionDef = _visit_function

    def visit_ClassDef(self, node):
        for deco in node.decorator_list:
            self.visit(deco)
        for base in node.bases:
            self.visit(base)
        tree = self.scope.tree
        self.bind(node.name, CLASS, node.lineno, node=node,
                  position=tree.definition_position(node))
        child = Scope(Scope.CLASS, node, self.scope, tree)
        self.scope.children.append(child)
        _Collector(child).visit_body(node.body)

    def visit_Lambda(self, node):
        pass

    def _visit_comprehension(self, node):
        for generator in node.generators:
            self.visit(generator.iter)
            break

    visit_ListComp = _visit_comprehension
    visit_SetComp = _visit_comprehension
    visit_DictComp = _visit_comprehension
    visit_GeneratorExp = _visit_comprehension

    # -- statements ------------------------------------------------------
    def visit_Global(self, node):
        self.scope.globals_declared.update(node.names)

    def visit_Assign(self, node):
        self.visit(node.value)
        for target in node.targets:
            self.bind_target(target, node.lineno, node.value)

    def visit_AnnAssign(self, node):
        if node.value is not None:
            self.visit(node.value)
        if isinstance(node.target, ast.Name):
            self.bind(node.target.id, ASSIGN, node.lineno, node=node.target,
                      position=_start(node.target), value=node.value, path=(),
                      annotation=node.annotation)
        else:
            self.visit(node.target)

    def visit_AugAssign(self, node):
        self.visit(node.value)
        if isinstance(node.target, ast.Name):
            name = node.target.id
            scope = self._target_scope(name)
            if not any(e.name == name for e in scope.events):
                self.bind(name, OTHER, node.lineno, node=node.target,
                          position=_start(node.target))
        else:
            self.visit(node.target)

    def visit_NamedExpr(self, node):
        self.visit(node.value)
        if isinstance(node.target, ast.Name):
            self.bind(node.target.id, ASSIGN, node.lineno, node=node.target,
                      position=_start(node.target), value=node.value, path=(),
                      annotation=None)

    def _visit_for(self, node):
        self.visit(node.iter)
        self.bind_plain(node.target, node.lineno, "for", node.iter)
        self.visit_body(node.body)
        self.visit_body(node.orelse)

    visit_For = _visit_for
    visit_AsyncFor = _visit_for

    def _visit_with(self, node):
        for item in node.items:
            self.visit(item.context_expr)
            if item.optional_vars is not None:
                self.bind_plain(item.optional_vars, node.lineno, "with", item.context_expr)
        self.visit_body(node.body)

    visit_With = _visit_with
    visit_AsyncWith = _visit_with

    def visit_ExceptHandler(self, node):
        if node.type is not None:
            self.visit(node.type)
        if node.name:
            tree = self.scope.tree
            position = tree.find_identifier(node.name, node.lineno, node.col_offset, "as")
            self.bind(node.name, EXCEPT, node.lineno, node=node, position=position,
                      type_expr=node.type)
        self.visit_body(node.body)

    def visit_Import(self, node):
        for alias in node.names:
            if alias.asname:
                self.bind(alias.asname, IMPORT, node.lineno, node=alias,
                          position=_as_position(alias), module=alias.name, as_name=True)
            else:
                first = alias.name.split(".")[0]
                self.bind(first, IMPORT, node.lineno, node=alias, position=_start(alias),
                          module=first, as_name=False)

    def visit_ImportFrom(self, node):
        module = node.module or ""
        for alias in node.names:
            if alias.name == "*":
                self.bind(None, STAR, node.lineno, node=alias, module=module, level=node.level)
            else:
                position = _as_position(alias) if alias.asname else _start(alias)
                self.bind(alias.asname or alias.name, IMPORT_FROM, node.lineno, node=alias,
                          position=position, module=module, level=node.level, attr=alias.name)

    def visit_MatchAs(self, node):
        if node.pattern is not None:
            self.visit(node.pattern)
        if node.name:
            position = (node.end_lineno, node.end_col_offset - len(node.name))
            self.bind(node.name, OTHER, node.lineno, node=node, position=position)

    def visit_MatchStar(self, node):
        if node.name:
            position = (node.end_lineno, node.end_col_offset - len(node.name))
            self.bind(node.name, OTHER, node.lineno, node=node, position=position)

    def visit_MatchMapping(self, node):
        self.generic_visit(node)
        if node.rest:
            position = self.scope.tree.find_identifier(node.rest, node.lineno, node.col_offset)
            self.bind(node.rest, OTHER, node.lineno, node=node, position=position)

    def visit_TypeAlias(self, node):
        if isinstance(node.name, ast.Name):
            self.bind(node.name.id, OTHER, node.lineno, node=node.name,
                      position=_start(node.name))


def _start(node):
    return (getattr(node, "lineno", 1), getattr(node, "col_offset", 0))


def _as_position(alias):
    """Position of the ``as`` name of an import alias."""
    return (alias.end_lineno, alias.end_col_offset - len(alias.asname))


def child_bind(scope, arg, function_node, **details):
    scope.events.append(Binding(arg.arg, PARAM, function_node.lineno, _Counter.next(), scope,
                                node=arg, position=_start(arg), stmt=function_node,
                                home=scope, **details))


def _collect_instance_attributes(class_scope, method_scope, body, self_name, initializer):
    """Record ``<self>.<attr> = ...`` assignments of a method on its class."""
    found = []

    def is_self_attr(target):
        return (isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name)
                and target.value.id == self_name)

    def record(target, statement, value, path, annotation=None):
        if is_self_attr(target):
            found.append(Binding(
                target.attr, ASSIGN, statement.lineno, _Counter.next(), method_scope,
                node=target, position=(target.end_lineno,
                                       target.end_col_offset - len(target.attr)),
                stmt=statement, home=method_scope, value=value, path=path,
                annotation=annotation, owner=class_scope))
        elif isinstance(target, (ast.Tuple, ast.List)):
            for index, element in enumerate(target.elts):
                record(element, statement, value, path + (index,))
        elif isinstance(target, ast.Starred):
            record(target.value, statement, None, ())

    for node in _walk_own(body):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                record(target, node, node.value, ())
        elif isinstance(node, ast.AnnAssign):
            record(node.target, node, node.value, (), node.annotation)
        elif isinstance(node, ast.AugAssign) and is_self_attr(node.target):
            if not any(e.name == node.target.attr for e in class_scope.instance_events + found):
                target = node.target
                found.append(Binding(
                    target.attr, OTHER, node.lineno, _Counter.next(), method_scope,
                    node=target, position=(target.end_lineno,
                                           target.end_col_offset - len(target.attr)),
                    stmt=node, home=method_scope, owner=class_scope))
    if initializer:
        class_scope.instance_events[:0] = found
    else:
        class_scope.instance_events.extend(found)

"""Static inference.

Secret: how bindings and expressions are mapped to values (modules, classes,
functions, instances), how names are resolved through scopes, flow states,
star imports and builtins, how narrowing conditions restrict values, and how
the members of a value are enumerated.

Clients see these abstractions:
  * ``Project``  - opens the main file and returns a ``Location`` for a cursor.
  * ``Where``    - an evaluation point: a scope plus the flow state there.
  * ``Value``    - has ``kind``, ``type_name`` and ``members()``; evaluation
                   always yields a list of possible values (a union).
  * ``Entity``   - a named member/visible name with ``presentation()`` giving
                   ``(kind, type_name)`` and ``values()`` giving its values.
Name resolution yields *targets*: ``scopes.Binding`` objects for names bound
in source, or ``Entity`` objects for names provided at runtime.
"""

import ast
import builtins
import io
import os
import types

from . import flow, introspect, scopes, vocabulary
from .modules import (DIRECTORY, RUNTIME, SOURCE, ModuleLocator, directory_module_names,
                      runtime_submodule_names)

MODULE = "module"
CLASS = "class"
FUNCTION = "function"
INSTANCE = "instance"
PARAM = "param"
STATEMENT = "statement"
UNKNOWN = "unknown"

_LITERAL_TYPES = {
    ast.JoinedStr: str,
    ast.ListComp: list,
    ast.DictComp: dict,
    ast.SetComp: set,
    ast.GeneratorExp: types.GeneratorType,
    ast.Compare: bool,
}
_SEQUENCE_TYPES = {ast.List: list, ast.Tuple: tuple, ast.Set: set}
_ARITHMETIC_TYPES = (int, float, complex, str, bytes, list, tuple)
_PROPERTY_DECORATORS = ("property", "cached_property")
_SPECIAL_BUILTINS = ("type", "getattr", "enumerate", "zip", "sorted", "list", "reversed",
                     "iter", "set", "frozenset", "tuple", "next")

_FUNCTION_RETURNS = {
    "len": int, "repr": str, "ascii": str, "chr": str, "ord": int, "hash": int, "id": int,
    "input": str, "format": str, "bin": str, "oct": str, "hex": str, "isinstance": bool,
    "issubclass": bool, "callable": bool, "hasattr": bool, "all": bool, "any": bool,
    "sorted": list, "dir": list, "vars": dict, "globals": dict, "locals": dict,
    "round": int, "divmod": tuple, "open": io.TextIOWrapper,
}
_FUNCTION_RETURNS = {getattr(builtins, name): result
                     for name, result in _FUNCTION_RETURNS.items() if hasattr(builtins, name)}


def _method_table():
    table = {}

    def add(owner, result, names):
        for name in names.split():
            table[(owner, name)] = result

    add(str, str, "upper lower strip lstrip rstrip replace format join title capitalize "
                  "casefold center ljust rjust zfill swapcase expandtabs removeprefix "
                  "removesuffix translate format_map")
    add(str, list, "split rsplit splitlines")
    add(str, bool, "startswith endswith isalpha isdigit isalnum isspace islower isupper "
                   "istitle isdecimal isnumeric isidentifier isprintable isascii")
    add(str, int, "find rfind index rindex count")
    add(str, bytes, "encode")
    add(str, tuple, "partition rpartition")
    add(bytes, str, "decode hex")
    add(bytes, bytes, "upper lower strip lstrip rstrip replace join")
    add(bytes, list, "split rsplit splitlines")
    add(list, list, "copy")
    add(list, int, "index count")
    add(tuple, int, "index count")
    add(dict, dict, "copy")
    add(dict, type({}.keys()), "keys")
    add(dict, type({}.values()), "values")
    add(dict, type({}.items()), "items")
    add(set, set, "copy union intersection difference symmetric_difference")
    add(set, bool, "issubset issuperset isdisjoint")
    add(frozenset, frozenset, "copy union intersection difference symmetric_difference")
    add(int, int, "bit_length bit_count conjugate")
    add(int, bytes, "to_bytes")
    add(float, bool, "is_integer")
    add(float, str, "hex")
    return table


_METHOD_RETURNS = _method_table()


class _Slice:
    """Marker for a slice subscript."""


SLICE = _Slice()
UNKNOWN_INDEX = _Slice()


# ---------------------------------------------------------------------------
# Evaluation points

class Where:
    """A scope plus the flow state (None: the state at the end of the scope).

    ``frame`` optionally supplies argument values for the parameters of a
    function scope being called; ``local_values`` maps names bound inside an
    expression (comprehension variables) to their values.
    """

    def __init__(self, scope, state=None, frame=None, local_values=None):
        self.scope = scope
        self.state = state
        self.frame = frame
        self.local_values = local_values


class Arguments:
    """The argument expressions of one call, with where they are evaluated."""

    def __init__(self, node, where):
        self.positional = node.args
        self.keywords = node.keywords
        self.where = where


class Frame:
    """Parameter values for one call of a function scope."""

    def __init__(self, scope, bound=None, arguments=None):
        self.scope = scope
        self._mapping = {}
        params = sorted((e for e in scope.events if e.form == scopes.PARAM),
                        key=lambda e: e.details["index"])
        positional = [p for p in params
                      if not p.details["star"] and not p.details.get("keyword_only")]
        if bound is not None and positional:
            self._mapping[id(positional[0])] = list(bound)
            positional = positional[1:]
        if arguments is None:
            return
        for index, node in enumerate(arguments.positional):
            if isinstance(node, ast.Starred) or index >= len(positional):
                break
            self._mapping[id(positional[index])] = (node, arguments.where)
        for keyword in arguments.keywords:
            for param in params:
                if keyword.arg is not None and param.name == keyword.arg \
                        and not param.details["star"]:
                    self._mapping[id(param)] = (keyword.value, arguments.where)

    def param_values(self, binding):
        entry = self._mapping.get(id(binding))
        if entry is None:
            return None
        if isinstance(entry, list):
            return entry
        node, where = entry
        return where.scope.tree.analysis.evaluate(node, where)


def _unique(values):
    seen = set()
    result = []
    for value in values:
        key = value.key()
        if key not in seen:
            seen.add(key)
            result.append(value)
    return result


# ---------------------------------------------------------------------------
# Values

class Value:
    kind = UNKNOWN
    type_name = None

    def key(self):
        return ("value", id(self))

    def members(self):
        return {}

    def attribute(self, name):
        entity = self.members().get(name)
        return entity.values() if entity is not None else []

    def attribute_targets(self, name):
        """Where attribute ``name`` is bound (Bindings or Entities)."""
        entity = self.members().get(name)
        return [entity] if entity is not None else []

    def call(self, arguments=None):
        return []

    def instantiate(self):
        return []

    def iterate(self):
        return []

    def subscript(self, index):
        return []

    def builtin_type(self):
        """For instances of builtin types, the type object; else None."""
        return None


class RuntimeValue(Value):
    """A live object obtained by importing a module."""

    def __init__(self, project, obj, owner=None):
        self.project = project
        self.obj = obj
        self._owner = owner
        self.kind = introspect.kind_of(obj)
        if self.kind == INSTANCE:
            self.type_name = introspect.type_name(obj)

    def key(self):
        return ("runtime", id(self.obj))

    def members(self):
        return {name: RuntimeEntity(self.project, name, self.obj)
                for name in introspect.attribute_names(self.obj)}

    def attribute(self, name):
        ok, value = introspect.get_attribute(self.obj, name)
        if ok:
            owner = self.obj if self.kind == CLASS else type(self.obj)
            return [RuntimeValue(self.project, value, owner)]
        if self.kind == MODULE:
            module_name = getattr(self.obj, "__name__", None)
            if module_name:
                found = self.project.module_value(module_name + "." + name)
                if found is not None:
                    return [found]
        return []

    def attribute_targets(self, name):
        ok, _ = introspect.get_attribute(self.obj, name)
        if ok:
            return [RuntimeEntity(self.project, name, self.obj)]
        return [ValueTarget(v) for v in self.attribute(name)]

    def call(self, arguments=None):
        if self.kind == CLASS:
            return self.instantiate()
        if self.kind == FUNCTION:
            try:
                result = _FUNCTION_RETURNS.get(self.obj)
            except TypeError:
                result = None
            if result is None and self._owner is not None:
                result = _method_return(self._owner, getattr(self.obj, "__name__", None))
            if result is not None:
                return [RuntimeInstance(self.project, result)]
        return []

    def instantiate(self):
        if self.kind == CLASS:
            return [RuntimeInstance(self.project, self.obj)]
        return []

    def iterate(self):
        if self.kind == INSTANCE:
            return RuntimeInstance(self.project, type(self.obj)).iterate()
        return []

    def subscript(self, index):
        if self.kind == CLASS:
            return [self]
        if self.kind == INSTANCE:
            return RuntimeInstance(self.project, type(self.obj)).subscript(index)
        return []

    def builtin_type(self):
        return type(self.obj) if self.kind == INSTANCE else None


def _method_return(owner, name):
    if not name or not isinstance(owner, type):
        return None
    for base in getattr(owner, "__mro__", (owner,)):
        result = _METHOD_RETURNS.get((base, name))
        if result is not None:
            return result
    return None


class RuntimeInstance(Value):
    """An instance of a runtime class, known only by its class."""

    kind = INSTANCE

    def __init__(self, project, cls):
        self.project = project
        self.cls = cls
        self._sample = introspect.sample_instance(cls)
        self.type_name = introspect.class_name(cls)

    def key(self):
        return ("instance", id(self.cls))

    def members(self):
        return {name: RuntimeEntity(self.project, name, self._sample, from_class=self.cls)
                for name in introspect.attribute_names(self.cls)}

    def attribute(self, name):
        return RuntimeEntity(self.project, name, self._sample, from_class=self.cls).values()

    def attribute_targets(self, name):
        if name in introspect.attribute_names(self.cls):
            return [RuntimeEntity(self.project, name, self._sample, from_class=self.cls)]
        return []

    def iterate(self):
        if issubclass(self.cls, str):
            return [RuntimeInstance(self.project, str)]
        if issubclass(self.cls, (bytes, bytearray, range)):
            return [RuntimeInstance(self.project, int)]
        return []

    def subscript(self, index):
        if index is SLICE and issubclass(self.cls, (str, bytes, list, tuple)):
            return [self]
        if issubclass(self.cls, str):
            return [RuntimeInstance(self.project, str)]
        if issubclass(self.cls, (bytes, bytearray)):
            return [RuntimeInstance(self.project, int)]
        return []

    def builtin_type(self):
        return self.cls


class SequenceInstance(RuntimeInstance):
    """A list/tuple/set display whose elements are known expressions."""

    def __init__(self, project, cls, node, where):
        RuntimeInstance.__init__(self, project, cls)
        self._node = node
        self._where = where

    def key(self):
        return ("display", id(self._node))

    def _analysis(self):
        return self._where.scope.tree.analysis

    def iterate(self):
        result = []
        for element in self._node.elts:
            if not isinstance(element, ast.Starred):
                result.extend(self._analysis().evaluate(element, self._where))
        return _unique(result)

    def subscript(self, index):
        if index is SLICE:
            return [self]
        elements = self._node.elts
        if isinstance(index, int) and not isinstance(index, bool) \
                and not any(isinstance(e, ast.Starred) for e in elements) \
                and -len(elements) <= index < len(elements) and self.cls is not set:
            return self._analysis().evaluate(elements[index], self._where)
        if self.cls is set:
            return []
        return self.iterate()


class ValueSequence(RuntimeInstance):
    """A container whose element values are known (one list per position).

    With ``positional`` the positions are fixed (a tuple); otherwise every
    element may be any of the listed values.
    """

    def __init__(self, project, cls, elements, positional=False):
        RuntimeInstance.__init__(self, project, cls)
        self._elements = elements
        self._positional = positional

    def key(self):
        return ("sequence", id(self))

    def iterate(self):
        return _unique([v for values in self._elements for v in values])

    def subscript(self, index):
        if index is SLICE:
            return [self]
        if self._positional and isinstance(index, int) and not isinstance(index, bool) \
                and -len(self._elements) <= index < len(self._elements):
            return self._elements[index]
        return self.iterate()


class DictInstance(RuntimeInstance):
    """A dict display whose keys and values are known expressions."""

    def __init__(self, project, node, where):
        RuntimeInstance.__init__(self, project, dict)
        self._node = node
        self._where = where

    def key(self):
        return ("display", id(self._node))

    def iterate(self):
        analysis = self._where.scope.tree.analysis
        result = []
        for key in self._node.keys:
            if key is not None:
                result.extend(analysis.evaluate(key, self._where))
        return _unique(result)

    def _values(self):
        analysis = self._where.scope.tree.analysis
        return _unique([v for k, value in zip(self._node.keys, self._node.values)
                        if k is not None for v in analysis.evaluate(value, self._where)])

    def attribute(self, name):
        if name in ("keys", "values", "items"):
            return [_DictView(self, name)]
        return RuntimeInstance.attribute(self, name)

    def subscript(self, index):
        analysis = self._where.scope.tree.analysis
        pairs = [(k, v) for k, v in zip(self._node.keys, self._node.values) if k is not None]
        if index is not UNKNOWN_INDEX and index is not SLICE:
            for key, value in pairs:
                if isinstance(key, ast.Constant) and type(key.value) is type(index) \
                        and key.value == index:
                    return analysis.evaluate(value, self._where)
        return _unique([v for _, value in pairs for v in analysis.evaluate(value, self._where)])


class _DictView(Value):
    """``keys``/``values``/``items`` of a dict display (a bound method)."""

    kind = FUNCTION

    def __init__(self, owner, which):
        self._owner = owner
        self.which = which

    def key(self):
        return ("dict-view", id(self._owner), self.which)

    def call(self, arguments=None):
        owner = self._owner
        project = owner.project
        keys, values = owner.iterate(), owner._values()
        if self.which == "keys":
            elements = [keys]
        elif self.which == "values":
            elements = [values]
        else:
            elements = [[ValueSequence(project, tuple, [keys, values], positional=True)]]
        return [ValueSequence(project, list, elements)]


class UnresolvedModule(Value):
    kind = MODULE


class DirectoryModule(Value):
    """A package directory without ``__init__.py``."""

    kind = MODULE

    def __init__(self, project, directory):
        self.project = project
        self.directory = directory

    def key(self):
        return ("directory", self.directory)

    def attribute(self, name):
        found = self.project.submodule_value(self.directory, name)
        return [found] if found is not None else []

    def attribute_targets(self, name):
        return [ValueTarget(v) for v in self.attribute(name)]


class StaticModule(Value):
    kind = MODULE

    def __init__(self, analysis):
        self.analysis = analysis

    def key(self):
        return ("module", self.analysis.path)

    def members(self):
        return self.analysis.module_members()

    def attribute_targets(self, name):
        analysis = self.analysis
        targets = [t for t, _ in analysis.resolve_local(name, Where(analysis.tree.module))]
        if targets:
            return targets
        package_dir = analysis.package_dir()
        if package_dir:
            found = analysis.project.submodule_value(package_dir, name)
            if found is not None:
                return [ValueTarget(found)]
        return []

    def attribute(self, name):
        result = []
        for target in self.attribute_targets(name):
            result.extend(self.analysis.target_values(target))
        return _unique(result)


class StaticFunction(Value):
    kind = FUNCTION

    def __init__(self, analysis, scope, bound=None):
        self.analysis = analysis
        self.scope = scope
        self.bound = bound  # values of the receiver for a bound method

    def key(self):
        return ("function", id(self.scope))

    def is_property(self):
        return any(name in _PROPERTY_DECORATORS for name in self.scope.decorator_names())

    def bind(self, receiver):
        """This function as a method looked up on ``receiver``."""
        decorators = self.scope.decorator_names()
        if "staticmethod" in decorators:
            return self
        if "classmethod" in decorators:
            if isinstance(receiver, StaticInstance):
                receiver = receiver.cls
            return StaticFunction(self.analysis, self.scope, [receiver])
        if receiver.kind == CLASS:
            return self
        return StaticFunction(self.analysis, self.scope, [receiver])

    def call(self, arguments=None):
        if self.scope.is_async():
            return []
        project = self.analysis.project
        key = ("call", id(self.scope))
        if not project.enter(key):
            return []
        try:
            frame = None
            if self.bound is not None or arguments is not None:
                frame = Frame(self.scope, self.bound, arguments)
            return self._returns(frame)
        finally:
            project.leave(key)

    def _returns(self, frame):
        analysis = self.analysis
        statements = self.scope.return_statements()
        if statements is None:
            return [RuntimeInstance(analysis.project, types.GeneratorType)]
        result = []
        for statement in statements:
            if statement.value is None:
                result.append(analysis.none_value())
            else:
                where = analysis.where_before(self.scope, statement)
                where.frame = frame
                result.extend(analysis.evaluate(statement.value, where))
        if not statements:
            result.append(analysis.none_value())
        result = _unique(result)
        if not result and self.scope.node.returns is not None:
            where = analysis.where_before(self.scope.parent, self.scope.node)
            result = analysis.annotation_values(self.scope.node.returns, where)
        return result


class StaticClass(Value):
    kind = CLASS

    def __init__(self, analysis, scope):
        self.analysis = analysis
        self.scope = scope
        self.name = scope.name

        self.name = scope.name

    def key(self):
        return ("class", id(self.scope))

    def bases(self):
        project = self.analysis.project
        key = ("bases", id(self.scope))
        if not project.enter(key):
            return []
        try:
            where = self.analysis.where_before(self.scope.parent, self.scope.node)
            result = []
            for expr in self.scope.base_expressions():
                for value in self.analysis.evaluate(expr, where):
                    if isinstance(value, StaticClass) and value.key() != self.key():
                        result.append(value)
            return _unique(result)
        finally:
            project.leave(key)

    def mro(self):
        return _linearize(self, set())

    def members(self):
        result = {}
        for cls in reversed(self.mro()):
            for event in cls.scope.all_events():
                if event.name and event.form != scopes.STAR:
                    result[event.name] = BindingEntity(cls.analysis, event)
        return result

    def instance_members(self):
        result = self.members()
        grouped = {}
        for cls in reversed(self.mro()):
            for event in cls.scope.instance_attribute_events():
                grouped.setdefault(event.name, []).append(event)
        for name, events in grouped.items():
            result[name] = AttributeEntity(self.analysis, events)
        return result

    def class_targets(self, name):
        for cls in self.mro():
            targets = [t for t, _ in cls.analysis.resolve_local(name, Where(cls.scope))]
            if targets:
                return targets
        return []

    def instance_targets(self, name):
        targets = []
        for cls in self.mro():
            targets.extend(e for e in cls.scope.instance_attribute_events() if e.name == name)
        return targets

    def attribute_targets(self, name):
        return self.class_targets(name)

    def attribute(self, name):
        result = []
        for target in self.class_targets(name):
            for value in self.analysis.target_values(target):
                result.append(value.bind(self) if isinstance(value, StaticFunction) else value)
        return _unique(result)

    def call(self, arguments=None):
        return [StaticInstance(self, arguments)]

    def instantiate(self):
        return [StaticInstance(self)]

    def subscript(self, index):
        return [self]

    def is_subclass_of(self, other):
        return any(cls.key() == other.key() for cls in self.mro())


class StaticInstance(Value):
    kind = INSTANCE

    def __init__(self, cls, arguments=None):
        self.cls = cls
        self.type_name = cls.name
        self.arguments = arguments  # constructor arguments, when known

    def key(self):
        return ("static-instance", self.cls.key())

    def members(self):
        return self.cls.instance_members()

    def attribute_targets(self, name):
        return self.cls.instance_targets(name) or self.cls.class_targets(name)

    def attribute(self, name):
        analysis = self.cls.analysis
        project = analysis.project
        key = ("attribute", self.cls.key(), name)
        if not project.enter(key):
            return []
        try:
            result = []
            for target in self.cls.instance_targets(name):
                method = target.home
                arguments = self.arguments if method.name == "__init__" else None
                frame = Frame(method, [self], arguments)
                result.extend(target.home.tree.analysis.binding_values(target, frame))
            if result or self.cls.instance_targets(name):
                return _unique(result)
            for target in self.cls.class_targets(name):
                for value in analysis.target_values(target):
                    if isinstance(value, StaticFunction):
                        value = value.bind(self)
                        if value.is_property():
                            result.extend(value.call())
                            continue
                    result.append(value)
            return _unique(result)
        finally:
            project.leave(key)

    def _dunder_call(self, name):
        result = []
        for value in self.attribute(name):
            result.extend(value.call())
        return _unique(result)

    def call(self, arguments=None):
        result = []
        for value in self.attribute("__call__"):
            result.extend(value.call(arguments))
        return _unique(result)

    def iterate(self):
        result = []
        for iterator in self._dunder_call("__iter__"):
            if isinstance(iterator, StaticInstance):
                result.extend(iterator._dunder_call("__next__"))
            else:
                result.extend(iterator.iterate())
        return _unique(result)

    def subscript(self, index):
        return self._dunder_call("__getitem__")


class ValueTarget:
    """A resolution target that is directly a value (e.g. a submodule)."""

    def __init__(self, value):
        self.value = value


def _linearize(cls, seen):
    """C3 linearization of statically known classes (DFS on conflict)."""
    if cls.key() in seen:
        return [cls]
    seen = seen | {cls.key()}
    bases = cls.bases()
    sequences = [_linearize(base, seen) for base in bases] + [list(bases)]
    result = [cls]
    sequences = [list(s) for s in sequences if s]
    while sequences:
        for sequence in sequences:
            head = sequence[0]
            if not any(head.key() in [c.key() for c in s[1:]] for s in sequences):
                break
        else:
            for sequence in sequences:
                for item in sequence:
                    if item.key() not in [c.key() for c in result]:
                        result.append(item)
            return result
        result.append(head)
        sequences = [[c for c in s if c.key() != head.key()] for s in sequences]
        sequences = [s for s in sequences if s]
    return result


# ---------------------------------------------------------------------------
# Entities

class Entity:
    name = None

    def presentation(self):
        return (STATEMENT, None)

    def values(self):
        return []


class RuntimeEntity(Entity):
    """An attribute of a live object, or of a class standing in for an instance."""

    def __init__(self, project, name, owner, from_class=None):
        self.project = project
        self.name = name
        self._owner = owner
        self._from_class = from_class

    def fetch(self):
        if self._owner is not None:
            return introspect.get_attribute(self._owner, self.name)
        ok, obj = introspect.get_attribute(self._from_class, self.name)
        if ok and introspect.is_data_descriptor(obj):
            return False, None
        return ok, obj

    def owner_name(self):
        """Qualified name of the object or class this is an attribute of."""
        owner = self._from_class if self._from_class is not None else self._owner
        if isinstance(owner, types.ModuleType):
            return owner.__name__
        if not isinstance(owner, type):
            owner = type(owner)
        return "%s.%s" % (owner.__module__, owner.__qualname__)

    def presentation(self):
        ok, obj = self.fetch()
        if not ok:
            return (STATEMENT, None)
        kind = introspect.kind_of(obj)
        if kind == INSTANCE:
            return (INSTANCE, introspect.type_name(obj))
        return (kind, None)

    def values(self):
        ok, obj = self.fetch()
        if not ok:
            return []
        owner = self._from_class
        if owner is None:
            owner = self._owner if isinstance(self._owner, type) else type(self._owner)
        return [RuntimeValue(self.project, obj, owner)]


class ValueEntity(Entity):
    """A name whose values are produced on demand (e.g. a submodule)."""

    def __init__(self, name, fetch, kind=None):
        self.name = name
        self._fetch = fetch
        self._kind = kind
        self._values = None

    def presentation(self):
        if self._kind is not None:
            return (self._kind, None)
        values = self.values()
        if not values:
            return (STATEMENT, None)
        if values[0].kind == INSTANCE:
            return (INSTANCE, values[0].type_name)
        if values[0].kind in (MODULE, CLASS, FUNCTION):
            return (values[0].kind, None)
        return (STATEMENT, None)

    def values(self):
        if self._values is None:
            found = self._fetch()
            self._values = [found] if isinstance(found, Value) else list(found or [])
        return list(self._values)


class BindingEntity(Entity):
    def __init__(self, analysis, binding):
        self._analysis = analysis
        self.binding = binding
        self.name = binding.name

    def presentation(self):
        form = self.binding.form
        if form == scopes.DEF:
            return (FUNCTION, None)
        if form == scopes.CLASS:
            return (CLASS, None)
        if form == scopes.PARAM:
            return (PARAM, None)
        if form == scopes.IMPORT:
            return (MODULE, None)
        if form in (scopes.IMPORT_FROM, scopes.ASSIGN, scopes.EXCEPT):
            values = self.values()
            value = values[0] if values else Value()
            if value.kind == INSTANCE:
                return (INSTANCE, value.type_name)
            if form == scopes.IMPORT_FROM and value.kind in (MODULE, CLASS, FUNCTION):
                return (value.kind, None)
        return (STATEMENT, None)

    def values(self):
        return self._analysis.binding_values(self.binding)


class AttributeEntity(Entity):
    """An instance attribute assigned (possibly several times) in methods."""

    def __init__(self, analysis, bindings):
        self._analysis = analysis
        self.bindings = bindings
        self.name = bindings[0].name

    def presentation(self):
        values = self.values()
        if values and values[0].kind == INSTANCE:
            return (INSTANCE, values[0].type_name)
        return (STATEMENT, None)

    def values(self):
        result = []
        for binding in self.bindings:
            result.extend(self._analysis.binding_values(binding))
        return _unique(result)


# ---------------------------------------------------------------------------
# Analysis of one file

class Analysis:
    """Inference over one source file."""

    def __init__(self, project, path, text):
        self.project = project
        self.path = path
        self.tree = scopes.ScopeTree(text, path)
        self.tree.analysis = self
        self._scope_by_node = {}
        self._index(self.tree.module)
        self._module_members = None
        self._flows = {}
        self._binding_cache = {}

    def _index(self, scope):
        for child in scope.children:
            self._scope_by_node[id(child.node)] = child
            self._index(child)

    def scope_of(self, node):
        return self._scope_by_node.get(id(node))

    def package_dir(self):
        if os.path.basename(self.path) == "__init__.py":
            return os.path.dirname(self.path)
        return None

    def location(self, line, col, indent):
        return Location(self, self.tree.scope_at(line, col), line, col, indent)

    def none_value(self):
        return RuntimeInstance(self.project, type(None))

    # -- flow ------------------------------------------------------------
    def flow(self, scope):
        analysis = scope.tree.analysis
        if analysis is not self:
            return analysis.flow(scope)
        found = self._flows.get(id(scope))
        if found is None:
            found = self._flows[id(scope)] = flow.Flow(scope)
        return found

    def where_before(self, scope, node):
        return Where(scope, self.flow(scope).state_before(node))

    # -- members ---------------------------------------------------------
    def module_members(self):
        if self._module_members is None:
            key = ("module", self.path)
            if not self.project.enter(key):
                return {}
            try:
                result = {}
                for event in self.tree.module.all_events():
                    self._apply(result, event)
                self._module_members = result
            finally:
                self.project.leave(key)
        return self._module_members

    def _apply(self, result, event):
        if event.form == scopes.STAR:
            result.update(self.star_members(event))
        elif event.name:
            result[event.name] = BindingEntity(self, event)

    def star_members(self, event):
        module = self.project.module_value(event.details["module"], event.details["level"],
                                           self.path)
        if module is None:
            return {}
        return self.project.exported_members(module)

    def dunder_all(self):
        """Names listed in this module's ``__all__``, or None without one."""
        key = ("__all__", self.path)
        if not self.project.enter(key):
            return None
        try:
            names = None
            for node in _module_level_nodes(self.tree.module.node.body):
                if isinstance(node, (ast.Assign, ast.AnnAssign)):
                    targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                    if any(isinstance(t, ast.Name) and t.id == "__all__" for t in targets) \
                            and node.value is not None:
                        names = self._all_names(node.value) or []
                elif isinstance(node, ast.AugAssign) and isinstance(node.target, ast.Name) \
                        and node.target.id == "__all__" and isinstance(node.op, ast.Add):
                    names = (names or []) + (self._all_names(node.value) or [])
                elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                        and isinstance(node.func.value, ast.Name) \
                        and node.func.value.id == "__all__" and names is not None \
                        and len(node.args) == 1:
                    method, arg = node.func.attr, node.args[0]
                    if method == "extend":
                        names = names + (self._all_names(arg) or [])
                    elif method == "append" and isinstance(arg, ast.Constant) \
                            and isinstance(arg.value, str):
                        names = names + [arg.value]
                    elif method == "remove" and isinstance(arg, ast.Constant):
                        names = [n for n in names if n != arg.value]
            return list(dict.fromkeys(names)) if names is not None else None
        finally:
            self.project.leave(key)

    def _all_names(self, node):
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            return [e.value for e in node.elts
                    if isinstance(e, ast.Constant) and isinstance(e.value, str)]
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            return (self._all_names(node.left) or []) + (self._all_names(node.right) or [])
        if isinstance(node, ast.Attribute) and node.attr == "__all__":
            names = []
            for value in self.evaluate(node.value, Where(self.tree.module)):
                found = self.project.dunder_all(value)
                if found:
                    names.extend(found)
            return names
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) \
                and node.func.id in ("list", "tuple") and len(node.args) == 1:
            return self._all_names(node.args[0])
        return None

    def visible(self, scope, line):
        result = {name: RuntimeEntity(self.project, name, vocabulary.builtin_namespace())
                  for name in vocabulary.builtin_names()}
        for level in reversed(scope.chain()):
            for event in level.events_until_line(line):
                self._apply(result, event)
        return result

    # -- name resolution -------------------------------------------------
    def resolve(self, name, where):
        """Targets ``name`` may refer to at ``where``: list of (target, constraints)."""
        scope = where.scope
        if scope.parent is not None and name in scope.globals_declared:
            module = scope
            while module.parent is not None:
                module = module.parent
            return self.resolve(name, Where(module))
        state = where.state if where.state is not None else self.flow(scope).end
        facts = state.facts(name)
        if facts:
            result = []
            for binding, constraints in sorted(facts, key=_fact_order):
                if binding is flow.OUTER:
                    for target, more in self._resolve_outer(name, scope):
                        result.append((target, more + constraints))
                else:
                    result.append((binding, constraints))
            return result
        for event in reversed(scope.events):
            if event.form == scopes.STAR:
                members = scope.tree.analysis.star_members(event)
                if name in members:
                    return [(members[name], ())]
        return self._resolve_outer(name, scope)

    def resolve_local(self, name, where):
        """Like ``resolve`` but without looking outside ``where.scope``."""
        state = where.state if where.state is not None else self.flow(where.scope).end
        facts = state.facts(name)
        if facts:
            return [(b, c) for b, c in sorted(facts, key=_fact_order) if b is not flow.OUTER]
        for event in reversed(where.scope.events):
            if event.form == scopes.STAR:
                members = where.scope.tree.analysis.star_members(event)
                if name in members:
                    return [(members[name], ())]
        return []

    def _resolve_outer(self, name, scope):
        parent = scope.parent
        while parent is not None and parent.kind == scopes.Scope.CLASS:
            parent = parent.parent
        if parent is None:
            if name in vocabulary.builtin_names():
                return [(RuntimeEntity(self.project, name, vocabulary.builtin_namespace()), ())]
            return []
        state = None
        if scope.kind == scopes.Scope.CLASS and scope.parent is parent:
            state = self.flow(parent).state_before(scope.node)
        return self.resolve(name, Where(parent, state))

    def target_values(self, target, frame=None):
        if isinstance(target, scopes.Binding):
            return target.home.tree.analysis.binding_values(target, frame)
        if isinstance(target, ValueTarget):
            return [target.value]
        return target.values()

    def name_values(self, name, where):
        if where.local_values and name in where.local_values:
            return where.local_values[name]
        result = []
        for target, constraints in self.resolve(name, where):
            values = self.target_values(target, where.frame)
            if constraints:
                values = self.narrow(values, constraints, where)
            result.extend(values)
        return _unique(result)

    def narrow(self, values, constraints, where):
        for constraint in constraints:
            if constraint.kind == flow.Constraint.NONE:
                if constraint.positive:
                    values = [self.none_value()]
                else:
                    values = [v for v in values if v.builtin_type() is not type(None)]
                continue
            classes = [c for c in self._class_values(constraint.expr, where)]
            if not classes:
                continue
            if constraint.positive:
                values = _unique([i for c in classes for i in c.instantiate()])
            else:
                values = [v for v in values if not any(_is_instance(v, c) for c in classes)]
        return values

    def _class_values(self, expr, where):
        if isinstance(expr, ast.Tuple):
            found = []
            for element in expr.elts:
                found.extend(self._class_values(element, where))
            return found
        return [v for v in self.evaluate(expr, where) if v.kind == CLASS]

    # -- bindings --------------------------------------------------------
    def binding_values(self, binding, frame=None):
        owner = binding.home.tree.analysis
        if owner is not self:
            return owner.binding_values(binding, frame)
        if frame is not None and binding.home is frame.scope:
            if binding.form == scopes.PARAM:
                found = frame.param_values(binding)
                if found:
                    return _unique(found)
            else:
                key = ("binding", id(binding), id(frame))
                if not self.project.enter(key):
                    return []
                try:
                    return _unique(self._binding_values(binding, frame))
                finally:
                    self.project.leave(key)
        cached = self._binding_cache.get(id(binding))
        if cached is not None:
            return cached
        key = ("binding", id(binding))
        if not self.project.enter(key):
            return []
        try:
            result = _unique(self._binding_values(binding))
        finally:
            self.project.leave(key)
        self._binding_cache[id(binding)] = result
        return result

    def _binding_values(self, binding, frame=None):
        form, details = binding.form, binding.details
        if form == scopes.DEF:
            return [StaticFunction(self, self.scope_of(binding.node))]
        if form == scopes.CLASS:
            return [StaticClass(self, self.scope_of(binding.node))]
        if form == scopes.PARAM:
            return self._param_values(binding)
        if form == scopes.IMPORT:
            found = self.project.module_value(details["module"], 0, self.path)
            return [found] if found is not None else []
        if form == scopes.IMPORT_FROM:
            return self._import_from_values(details)
        where = self.where_before(binding.home, binding.stmt) if binding.stmt is not None \
            else Where(binding.home)
        where.frame = frame
        if form == scopes.ASSIGN:
            if details.get("starred"):
                return [RuntimeInstance(self.project, list)]
            if details.get("annotation") is not None:
                annotated = self.annotation_values(details["annotation"], where)
                if annotated:
                    return annotated

                    return annotated
            return self._unpacked(details.get("value"), details.get("path", ()), where)
        if form == scopes.OTHER and details.get("value") is not None:
            values = self.evaluate(details["value"], where)
            if details.get("source") == "for":
                values = [item for value in values for item in value.iterate()]
            elif details.get("source") == "with":
                values = [entered for value in values for entered in _entered(value)]
            return self.index_path(values, details.get("path", ()))
        if form == scopes.EXCEPT and details["type_expr"] is not None:
            return [i for c in self._class_values(details["type_expr"], where)
                    for i in c.instantiate()]
        return []

    def _unpacked(self, expr, path, where):
        if expr is None:
            return []
        direct = _unpack(expr, path)
        if direct is not None:
            return self.evaluate(direct, where)
        return self.index_path(self.evaluate(expr, where), path)

    @staticmethod
    def index_path(values, path):
        for index in path:
            values = _unique([item for value in values for item in value.subscript(index)])
        return values

    def _param_values(self, binding):
        details = binding.details
        function = details["function"]
        owner = function.class_scope()
        if details["index"] == 0 and owner is not None and not details["star"]:
            decorators = function.decorator_names()
            if "staticmethod" not in decorators:
                cls = StaticClass(self, owner)
                return [cls] if "classmethod" in decorators else cls.instantiate()
        if details["star"] == "*":
            return [RuntimeInstance(self.project, tuple)]
        if details["star"] == "**":
            return [RuntimeInstance(self.project, dict)]
        where = self.where_before(function.parent, function.node)
        if details["annotation"] is not None:
            annotated = self.annotation_values(details["annotation"], where)
            if annotated:
                return annotated
        if details.get("default") is not None:
            return self.evaluate(details["default"], where)
        return []

    def _import_from_values(self, details):
        module_name, level, attr = details["module"], details["level"], details["attr"]
        module = self.project.module_value(module_name, level, self.path)
        if module is not None:
            values = module.attribute(attr)
            if values:
                return values
        dotted = module_name + "." + attr if module_name else attr
        sub = self.project.module_value(dotted, level, self.path)
        return [sub] if sub is not None else []

    def import_from_targets(self, binding):
        """Where an imported name is bound in its own module."""
        details = binding.details
        module = self.project.module_value(details["module"], details["level"], self.path)
        if module is not None:
            targets = module.attribute_targets(details["attr"])
            if targets:
                return targets
        return []

    # -- annotations -----------------------------------------------------
    def annotation_values(self, node, where):
        if isinstance(node, ast.Constant):
            if node.value is None:
                return [self.none_value()]
            if isinstance(node.value, str):
                try:
                    parsed = ast.parse(node.value.strip(), mode="eval").body
                except (SyntaxError, ValueError, RecursionError, MemoryError):
                    return []
                return self.annotation_values(parsed, where)
            return []
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitOr):
            return _unique(self.annotation_values(node.left, where)
                           + self.annotation_values(node.right, where))
        if isinstance(node, ast.Subscript):
            head = _terminal_name(node.value)
            args = node.slice.elts if isinstance(node.slice, ast.Tuple) else [node.slice]
            if head == "Optional":
                return _unique(self.annotation_values(args[0], where) + [self.none_value()])
            if head == "Union":
                return _unique([v for a in args for v in self.annotation_values(a, where)])
            if head in ("Annotated", "ClassVar", "Final", "Required", "NotRequired",
                        "ReadOnly"):
                return self.annotation_values(args[0], where)
            if head in ("Type", "type"):
                return [v for v in self.evaluate(args[0], where) if v.kind == CLASS]
            return self._instances_of(self.evaluate(node.value, where))
        return self._instances_of(self.evaluate(node, where))

    def _instances_of(self, values):
        result = []
        for value in values:
            if value.kind == CLASS:
                result.extend(value.instantiate())
            elif isinstance(value, RuntimeValue):
                origin = getattr(value.obj, "__origin__", None)
                if isinstance(origin, type):
                    result.append(RuntimeInstance(self.project, origin))
        return _unique(result)

    # -- expressions -----------------------------------------------------
    def evaluate(self, node, where):
        project = self.project
        if isinstance(node, ast.Constant):
            return [RuntimeInstance(project, type(node.value))]
        sequence = _SEQUENCE_TYPES.get(type(node))
        if sequence is not None:
            return [SequenceInstance(project, sequence, node, where)]
        if isinstance(node, ast.Dict):
            return [DictInstance(project, node, where)]
        literal = _LITERAL_TYPES.get(type(node))
        if literal is not None:
            return [RuntimeInstance(project, literal)]
        if isinstance(node, ast.Name):
            return self.name_values(node.id, where)
        if isinstance(node, ast.Attribute):
            result = []
            for value in self.evaluate(node.value, where):
                result.extend(value.attribute(node.attr))
            return _unique(result)
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name) and node.func.id == "super":
                found = self._super_values(where)
                if found is not None:
                    return found
            if isinstance(node.func, ast.Name) and node.func.id in _SPECIAL_BUILTINS:
                found = self._builtin_call(node, where)
                if found is not None:
                    return found
            arguments = Arguments(node, where)
            result = []
            for value in self.evaluate(node.func, where):
                result.extend(value.call(arguments))
            return _unique(result)
        if isinstance(node, ast.Subscript):
            index = _index_of(node.slice)
            result = []
            for value in self.evaluate(node.value, where):
                result.extend(value.subscript(index))
            return _unique(result)
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return [RuntimeInstance(project, bool)]
            return self.evaluate(node.operand, where)
        if isinstance(node, ast.BinOp):
            return self._binary(node, where)
        if isinstance(node, ast.BoolOp):
            return _unique([v for operand in node.values for v in self.evaluate(operand, where)])
        if isinstance(node, ast.IfExp):
            return _unique(self.evaluate(node.body, where) + self.evaluate(node.orelse, where))
        if isinstance(node, ast.NamedExpr):
            return self.evaluate(node.value, where)
        return []

    def _binary(self, node, where):
        result = []
        lefts = self.evaluate(node.left, where)
        rights = None
        for left in lefts:
            left_type = left.builtin_type()
            if left_type is str and isinstance(node.op, ast.Mod):
                result.append(left)
                continue
            if rights is None:
                rights = self.evaluate(node.right, where)
            for right in rights:
                if left_type is not None and left_type is right.builtin_type() \
                        and left_type in _ARITHMETIC_TYPES:
                    result.append(RuntimeInstance(self.project, left_type))
        return _unique(result)

    def _builtin_call(self, node, where):
        """Calls of builtins whose result depends on their arguments."""
        name = node.func.id
        functions = self.evaluate(node.func, where)
        if len(functions) != 1 or not isinstance(functions[0], RuntimeValue) \
                or functions[0].obj is not getattr(builtins, name, None) \
                or any(isinstance(a, ast.Starred) for a in node.args):
            return None
        args = node.args
        project = self.project
        if name == "type" and len(args) == 1:
            result = []
            for value in self.evaluate(args[0], where):
                if isinstance(value, StaticInstance):
                    result.append(value.cls)
                elif isinstance(value, RuntimeInstance):
                    result.append(RuntimeValue(project, value.cls))
            return _unique(result)
        if name == "getattr" and len(args) >= 2 and isinstance(args[1], ast.Constant) \
                and isinstance(args[1].value, str):
            result = []
            for value in self.evaluate(args[0], where):
                result.extend(value.attribute(args[1].value))
            if len(args) > 2:
                result.extend(self.evaluate(args[2], where))
            return _unique(result)
        if not args:
            return None
        items = [[v for value in self.evaluate(a, where) for v in value.iterate()]
                 for a in args]
        if name == "enumerate":
            pair = ValueSequence(project, tuple, [[RuntimeInstance(project, int)], items[0]],
                                 positional=True)
            return [ValueSequence(project, enumerate, [[pair]])]
        if name == "zip":
            group = ValueSequence(project, tuple, items, positional=True)
            return [ValueSequence(project, zip, [[group]])]
        if name in ("sorted", "list", "reversed", "iter"):
            cls = {"sorted": list, "list": list, "reversed": reversed, "iter": type(iter([]))}
            return [ValueSequence(project, cls[name], [items[0]])]
        if name in ("set", "frozenset", "tuple"):
            return [ValueSequence(project, getattr(builtins, name), [items[0]])]
        if name == "next":
            return items[0]
        return None

    def _super_values(self, where):
        scope = where.scope
        owner = scope.class_scope() if scope.kind == scopes.Scope.FUNCTION else None
        if owner is None:
            return None
        cls = StaticClass(owner.tree.analysis, owner)
        params = sorted((e for e in scope.events if e.form == scopes.PARAM),
                        key=lambda e: e.details["index"])
        receivers = self.name_values(params[0].name, where) if params else []
        arguments = [r.arguments for r in receivers if isinstance(r, StaticInstance)] or [None]
        return _unique([StaticInstance(base, arguments[0]) for base in cls.bases()])


def _module_level_nodes(statements):
    """Nodes executed at module level (nested scopes are not entered)."""
    stack = list(reversed(statements))
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(node))))


def _fact_order(fact):
    binding = fact[0]
    return getattr(binding, "order", 0)


def _is_instance(value, cls):
    if isinstance(value, StaticInstance) and isinstance(cls, StaticClass):
        return value.cls.is_subclass_of(cls)
    if isinstance(cls, RuntimeValue) and value.builtin_type() is not None:
        try:
            return issubclass(value.builtin_type(), cls.obj)
        except TypeError:
            return False
    return False


def _entered(value):
    if isinstance(value, StaticInstance):
        entered = value._dunder_call("__enter__")
        if entered:
            return entered
    return [value]


def _terminal_name(node):
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return None


def _index_of(node):
    if isinstance(node, ast.Slice):
        return SLICE
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub) \
            and isinstance(node.operand, ast.Constant) and isinstance(node.operand.value, int):
        return -node.operand.value
    return UNKNOWN_INDEX


def _unpack(expr, path):
    for index in path:
        if not isinstance(expr, (ast.Tuple, ast.List)):
            return None
        if any(isinstance(e, ast.Starred) for e in expr.elts) or index >= len(expr.elts):
            return None
        expr = expr.elts[index]
    return expr


class Location:
    """A cursor position inside the main file (for completion)."""

    def __init__(self, analysis, scope, line, col, indent):
        self._analysis = analysis
        self._scope = scope
        self._line = line
        self._where = Where(scope, analysis.flow(scope).state_at(line, col, indent))

    def visible_entities(self):
        return self._analysis.visible(self._scope, self._line)

    def evaluate(self, expression_text):
        """Possible values of an expression written at the cursor."""
        try:
            node = ast.parse(expression_text.strip(), mode="eval").body
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            return []
        return self._analysis.evaluate(node, self._where)


# ---------------------------------------------------------------------------
# Project

class Project:
    def __init__(self, main_path, main_text, root=None):
        self._main_path = os.path.abspath(main_path)
        self.root = os.path.abspath(root) if root else os.path.dirname(self._main_path)
        self._locator = ModuleLocator(self.root)
        self._analyses = {}
        self._active = set()
        self.main = Analysis(self, self._main_path, main_text)
        self._analyses[self._main_path] = self.main

    def enter(self, key):
        if key in self._active:
            return False
        self._active.add(key)
        return True

    def leave(self, key):
        self._active.discard(key)

    def location(self, line, col, indent=0):
        return self.main.location(line, col, indent)

    def module_value(self, dotted, level=0, importer_path=None):
        located = self._locator.locate(dotted, level, importer_path or self._main_path)
        return self._wrap(located)

    def submodule_value(self, directory, name):
        return self._wrap(self._locator.locate_in_directory(directory, name))

    # -- module contents -------------------------------------------------
    def dunder_all(self, module):
        """The ``__all__`` names of a module value, or None."""
        if isinstance(module, StaticModule):
            return module.analysis.dunder_all()
        if isinstance(module, RuntimeValue) and module.kind == MODULE:
            ok, names = introspect.get_attribute(module.obj, "__all__")
            if ok and isinstance(names, (list, tuple)):
                return [n for n in names if isinstance(n, str)]
        return None

    def exported_members(self, module):
        """Names ``from <module> import *`` binds: dict of name -> Entity."""
        if module.kind != MODULE:
            return {}
        members = module.members()
        names = self.dunder_all(module)
        if names is None:
            return {name: entity for name, entity in members.items()
                    if not name.startswith("_")}
        result = {}
        for name in names:
            if name in members:
                result[name] = members[name]
            else:
                result[name] = ValueEntity(name, lambda n=name: module.attribute(n))
        return result

    def importable_members(self, module):
        """Names offered after ``from <module> import``: dict of name -> Entity."""
        result = self.exported_members(module)
        if self.dunder_all(module) is not None:
            return result
        for name, entity in self.submodule_entities(module).items():
            if not name.startswith("_"):
                result.setdefault(name, entity)
        return result

    def submodule_entities(self, module):
        """Submodules of a package value: dict of name -> Entity."""
        names = set()
        directory = None
        if isinstance(module, StaticModule):
            directory = module.analysis.package_dir()
        elif isinstance(module, DirectoryModule):
            directory = module.directory
        elif isinstance(module, RuntimeValue) and module.kind == MODULE:
            names = runtime_submodule_names(module.obj)
            prefix = module.obj.__name__
            return {name: ValueEntity(name, lambda n=name: self.module_value(prefix + "." + n),
                                      MODULE) for name in names}
        if directory is None:
            return {}
        names = directory_module_names(directory)
        return {name: ValueEntity(name, lambda n=name: self.submodule_value(directory, n),
                                  MODULE) for name in names}

    def module_names(self, dotted="", level=0):
        """Modules importable as ``[.*]<dotted>.<name>``: dict of name -> Entity."""
        if not dotted and level == 0:
            return {name: ValueEntity(name, lambda n=name: self.module_value(n), MODULE)
                    for name in self._locator.top_level_names(self._main_path)}
        if not dotted:
            base = self._locator.relative_base(level, self._main_path)
            if base is None:
                return {}
            return self.submodule_entities(DirectoryModule(self, base))
        module = self.module_value(dotted, level)
        return self.submodule_entities(module) if module is not None else {}

    def _wrap(self, located):
        if located is None:
            return None
        if located.how == RUNTIME:
            return RuntimeValue(self, located.module)
        if located.how == DIRECTORY:
            return DirectoryModule(self, located.path)
        if located.how == SOURCE:
            return StaticModule(self._analysis_for(located.path))
        return None

    def _analysis_for(self, path):
        path = os.path.abspath(path)
        if path not in self._analyses:
            try:
                with open(path, "rb") as handle:
                    text = handle.read().decode("utf-8", errors="replace")
            except OSError:
                text = ""
            self._analyses[path] = Analysis(self, path, text)
        return self._analyses[path]

"""Flow analysis.

Secret: how control flow inside one scope is approximated — which bindings
of a name can reach a statement (branches merge, ``return``/``raise``/
``break``/``continue`` end a path, loops run zero or one time, handlers see
any prefix of their ``try`` body) and which narrowing conditions
(``isinstance`` checks, ``is None`` tests, asserts) hold there.

A state maps a name to a set of facts ``(binding, constraints)``. The binding
``OUTER`` stands for "whatever the enclosing scope provides"; it only appears
when a name that is not bound locally gets narrowed.
"""

import ast

from . import scopes

OUTER = None


class Constraint:
    """A condition known to hold for a name: ``isinstance`` or ``is None``."""

    ISINSTANCE, NONE = "isinstance", "none"

    def __init__(self, kind, positive, expr=None):
        self.kind = kind
        self.positive = positive
        self.expr = expr

    def negated(self):
        return Constraint(self.kind, not self.positive, self.expr)


class State:
    def __init__(self, names=None, dead=False):
        self.names = names if names is not None else {}
        self.dead = dead

    def facts(self, name):
        return self.names.get(name)

    def bound(self, binding):
        names = dict(self.names)
        names[binding.name] = frozenset([(binding, ())])
        return State(names, self.dead)

    def narrowed(self, conditions):
        if not conditions:
            return self
        names = dict(self.names)
        for name, constraint in conditions:
            facts = names.get(name) or frozenset([(OUTER, ())])
            names[name] = frozenset((b, c + (constraint,)) for b, c in facts)
        return State(names, self.dead)

    def killed(self):
        return State(self.names, True)


def merge(states, keep_dead=False):
    """Join the states of paths meeting at one point."""
    states = [s for s in states if s is not None]
    live = [s for s in states if not s.dead]
    pool = states if keep_dead or not live else live
    if not pool:
        return State(dead=True)
    if len(pool) == 1:
        return State(pool[0].names, not live and not keep_dead)
    names = {}
    for state in pool:
        for name in state.names:
            names.setdefault(name, None)
    for name in names:
        facts = set()
        missing = False
        for state in pool:
            found = state.names.get(name)
            if found is None:
                missing = True
            else:
                facts.update(found)
        if missing and any(b is OUTER for b, _ in facts):
            facts.add((OUTER, ()))
        names[name] = frozenset(facts)
    return State(names, not live and not keep_dead)


class _Loop:
    def __init__(self):
        self.breaks = []
        self.continues = []


class Flow:
    """Reaching bindings at every statement of one scope."""

    def __init__(self, scope):
        self.scope = scope
        self.before = {}
        self.after = {}
        self._exits = []
        self._by_stmt = {}
        stray = []
        start = State()
        for event in scope.events:
            if not event.name or event.form == scopes.STAR:
                continue
            if event.form == scopes.PARAM:
                start = start.bound(event)
            elif event.home is scope and event.stmt is not None:
                self._by_stmt.setdefault(id(event.stmt), []).append(event)
            else:
                stray.append(event)
        body = scope.node.body if scope.node is not None else []
        last = self._block(body, start, None)
        end = merge([last] + self._exits, keep_dead=True)
        for event in stray:
            facts = set(end.names.get(event.name, ()))
            facts.add((event, ()))
            end.names[event.name] = frozenset(facts)
        self.end = end
        self.body = body

    # -- statements ------------------------------------------------------
    def _apply(self, node, state):
        for event in self._by_stmt.get(id(node), ()):
            state = state.bound(event)
        return state

    def _block(self, statements, state, loop):
        for statement in statements:
            self.before[id(statement)] = state
            state = self._statement(statement, state, loop)
            self.after[id(statement)] = state
        return state

    def _statement(self, node, state, loop):
        if isinstance(node, ast.If):
            state = self._apply(node, state)
            positive, negative = conditions(node.test)
            body = self._block(node.body, state.narrowed(positive), loop)
            other = self._block(node.orelse, state.narrowed(negative), loop)
            merged = merge([body, other])
            if not body.dead and not other.dead:
                merged = _forget(merged, positive, negative)
            return merged
        if isinstance(node, ast.While):
            state = self._apply(node, state)
            positive, negative = conditions(node.test)
            inner = _Loop()
            body = self._block(node.body, state.narrowed(positive), inner)
            if _always_true(node.test):
                normal = State(state.names, True)
            else:
                normal = merge([state, body] + inner.continues).narrowed(negative)
            other = self._block(node.orelse, normal, loop)
            return merge([other] + inner.breaks)
        if isinstance(node, (ast.For, ast.AsyncFor)):
            inner = _Loop()
            body = self._block(node.body, self._apply(node, state), inner)
            normal = merge([state, body] + inner.continues)
            other = self._block(node.orelse, normal, loop)
            return merge([other] + inner.breaks)
        if isinstance(node, (ast.With, ast.AsyncWith)):
            return self._block(node.body, self._apply(node, state), loop)
        if isinstance(node, (ast.Try, getattr(ast, "TryStar", ast.Try))):
            return self._try(node, state, loop)
        if isinstance(node, ast.Match):
            state = self._apply(node, state)
            ends = []
            exhaustive = False
            for case in node.cases:
                start = self._apply(case, state)
                self.before[id(case)] = start
                ends.append(self._block(case.body, start, loop))
                if case.guard is None and isinstance(case.pattern, ast.MatchAs) \
                        and case.pattern.pattern is None:
                    exhaustive = True
            if not exhaustive:
                ends.append(state)
            return merge(ends)
        if isinstance(node, (ast.Return, ast.Raise)):
            state = self._apply(node, state)
            self._exits.append(state)
            return state.killed()
        if isinstance(node, ast.Break):
            if loop is not None:
                loop.breaks.append(state)
            return state.killed()
        if isinstance(node, ast.Continue):
            if loop is not None:
                loop.continues.append(state)
            return state.killed()
        if isinstance(node, ast.Assert):
            state = self._apply(node, state)
            return state.narrowed(conditions(node.test)[0])
        return self._apply(node, state)

    def _try(self, node, state, loop):
        body = self._block(node.body, state, loop)
        partial = [state] + [self.after[id(s)] for s in node.body if id(s) in self.after]
        handler_start = merge(partial, keep_dead=True)
        ends = []
        for handler in node.handlers:
            start = self._apply(handler, handler_start)
            self.before[id(handler)] = start
            ends.append(self._block(handler.body, start, loop))
        ends.insert(0, self._block(node.orelse, body, loop))
        joined = merge(ends)
        if node.finalbody:
            start = merge(ends + [handler_start], keep_dead=True) if joined.dead else joined
            final = self._block(node.finalbody, start, loop)
            return State(final.names, joined.dead or final.dead)
        return joined

    # -- queries ---------------------------------------------------------
    def state_before(self, node):
        """State just before ``node`` (a statement, handler or case) runs."""
        return self.before.get(id(node))

    def state_at(self, line, col, indent):
        """State at a cursor that may sit between or after statements.

        ``indent`` is the indentation of the cursor's line (used to decide
        which block an empty or broken line belongs to).
        """
        return self._find(self.body, line, col, indent, self.end)

    def _find(self, statements, line, col, indent, fallback):
        previous = None
        for statement in statements:
            if (statement.lineno, statement.col_offset) > (line, col):
                break
            previous = statement
        if previous is None:
            return self.before.get(id(statements[0]), fallback) if statements else fallback
        blocks = _blocks(previous)
        if line <= (previous.end_lineno or previous.lineno):
            inner = [block for block in blocks
                     if (block[0].lineno, block[0].col_offset) <= (line, col)
                     or block[0].lineno < line]
            if inner:
                block = inner[-1]
                return self._find(block, line, col, indent,
                                  self.after.get(id(block[-1]), fallback))
            return self.before.get(id(previous), fallback)
        if blocks and indent > previous.col_offset:
            block = blocks[-1]
            return self._find(block, line, col, indent, self.after.get(id(block[-1]), fallback))
        return self.after.get(id(previous), fallback)


def _forget(state, positive, negative):
    """Drop narrowing by one test where both of its outcomes rejoin.

    A binding narrowed one way on the true path and the other way on the
    false path is, after the paths meet, just the binding again. (When one
    path rebinds the name, the other path's narrowing is kept.)
    """
    own = {id(c) for _, c in positive + negative}
    if not own:
        return state
    names = dict(state.names)
    for name, facts in state.names.items():
        groups = {}
        for binding, constraints in facts:
            base = tuple(c for c in constraints if id(c) not in own)
            groups.setdefault((binding, base), []).append(constraints)
        if all(len(variants) == 1 for variants in groups.values()):
            continue
        result = set()
        for (binding, base), variants in groups.items():
            if len(variants) > 1:
                result.add((binding, base))
            else:
                result.add((binding, variants[0]))
        names[name] = frozenset(result)
    return State(names, state.dead)


def _blocks(node):
    """Nested non-empty statement lists of a compound statement, in source order."""
    found = []
    for field in ("body", "handlers", "orelse", "finalbody", "cases"):
        value = getattr(node, field, None)
        if not value or not isinstance(value, list):
            continue
        if field in ("handlers", "cases"):
            found.extend(item.body for item in value if item.body)
        else:
            found.append(value)
    found.sort(key=lambda block: (block[0].lineno, block[0].col_offset))
    return found


def _always_true(test):
    return isinstance(test, ast.Constant) and bool(test.value)


def conditions(test):
    """``(holds_if_true, holds_if_false)``: lists of (name, Constraint)."""
    if isinstance(test, ast.UnaryOp) and isinstance(test.op, ast.Not):
        positive, negative = conditions(test.operand)
        return negative, positive
    if isinstance(test, ast.BoolOp):
        parts = [conditions(value) for value in test.values]
        if isinstance(test.op, ast.And):
            return [c for p, _ in parts for c in p], []
        return [], [c for _, n in parts for c in n]
    if isinstance(test, ast.NamedExpr):
        return conditions(test.value)
    if isinstance(test, ast.Call) and isinstance(test.func, ast.Name) \
            and test.func.id == "isinstance" and len(test.args) == 2 \
            and isinstance(test.args[0], ast.Name):
        constraint = Constraint(Constraint.ISINSTANCE, True, test.args[1])
        name = test.args[0].id
        return [(name, constraint)], [(name, constraint.negated())]
    if isinstance(test, ast.Compare) and len(test.ops) == 1:
        left, right = test.left, test.comparators[0]
        if _is_none(left):
            left, right = right, left
        if isinstance(left, ast.Name) and _is_none(right):
            op = test.ops[0]
            if isinstance(op, (ast.Is, ast.Eq)):
                positive = True
            elif isinstance(op, (ast.IsNot, ast.NotEq)):
                positive = False
            else:
                return [], []
            constraint = Constraint(Constraint.NONE, positive)
            return [(left.id, constraint)], [(left.id, constraint.negated())]
    return [], []


def _is_none(node):
    return isinstance(node, ast.Constant) and node.value is None
"""Cursor context detection.

Secret: how the text before the cursor is lexed to decide whether a bare
name, an attribute, a module in an import statement, a name imported from a
module, or nothing is being completed, what prefix has been typed, and which
source text forms the receiver of an attribute access (or which module an
import refers to).
"""

import re

NAME = "name"
ATTRIBUTE = "attribute"
IMPORT_MODULE = "import_module"  # ``import a.b|`` / ``from .a|``: module names
IMPORT_NAME = "import_name"      # ``from a import b|``: names inside a module
KEYWORDS = "keywords"            # only the listed keywords fit (``from a imp|``)
NONE = "none"

_DOTTED = r"[^\W\d]\w*(?:\s*\.\s*[^\W\d]\w*)*"
_IMPORT_ITEM_RE = re.compile(r"^(?:(%s)\s*\.\s*)?(\w*)$" % _DOTTED)
_FROM_MODULE_RE = re.compile(r"^from\s*((?:\.\s*)*)(?:(%s)\s*\.\s*)?(\w*)$" % _DOTTED)
_FROM_IMPORT_RE = re.compile(r"^from\s*((?:\.\s*)*)(%s)?\s*(?<![\w])import(?=[\s(])\s*\(?(.*)$"
                             % _DOTTED, re.S)
_FROM_KEYWORD_RE = re.compile(r"^from\s*((?:\.\s*)*)(%s)?\s+(\w*)$" % _DOTTED)

_CLOSERS = {")": "(", "]": "[", "}": "{"}
_STRING_PREFIX_CHARS = set("rRbBuUfF")


class CursorContext:
    def __init__(self, kind, prefix="", receiver=None, module="", level=0, words=()):
        self.kind = kind
        self.prefix = prefix
        self.receiver = receiver
        self.module = module  # import contexts: dotted module name (may be "")
        self.level = level    # import contexts: leading dots of a relative import
        self.words = list(words)


def analyze(text_before):
    """Classify the cursor at the end of ``text_before``."""
    if _inside_string_or_comment(text_before):
        return CursorContext(NONE)
    end = len(text_before)
    start = end
    while start > 0 and _is_ident_char(text_before[start - 1]):
        start -= 1
    prefix = text_before[start:end]
    if prefix and prefix[0].isdigit():
        return CursorContext(NONE)
    statement = _import_statement(text_before)
    if statement is not None:
        return _import_context(statement)
    pos = _skip_space_back(text_before, start)
    if pos > 0 and text_before[pos - 1] == ".":
        dot = pos - 1
        receiver = _receiver_before(text_before, dot)
        if receiver is None:
            return CursorContext(NONE)
        return CursorContext(ATTRIBUTE, prefix, receiver)
    return CursorContext(NAME, prefix)


def _import_statement(text):
    """The current statement up to the cursor if it is an import, else None."""
    start = _statement_start(text)
    statement = text[start:].replace("\\\n", " ")
    statement = re.sub(r"#[^\n]*", "", statement)
    statement = statement.lstrip()
    if re.match(r"(import|from)\b", statement) and statement not in ("import", "from"):
        return statement
    return None


def _statement_start(text):
    """Index where the logical statement containing the end of ``text`` begins."""
    start = 0
    depth = 0
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == "#":
            newline = text.find("\n", i)
            if newline < 0:
                break
            i = newline
            continue
        if ch in "'\"":
            quote = text[i : i + 3] if text[i : i + 3] in ("'''", '"""') else ch
            i += len(quote)
            while i < n and not text.startswith(quote, i):
                if text[i] == "\\":
                    i += 1
                elif text[i] == "\n" and len(quote) == 1:
                    break
                i += 1
            i += len(quote)
            continue
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth = max(0, depth - 1)
        elif ch == "\n":
            if i > 0 and text[i - 1] == "\\":
                pass
            elif depth == 0:
                start = i + 1
        elif ch == ";" and depth == 0:
            start = i + 1
        elif ch == ":" and depth == 0 and _ends_block_header(text, start, i):
            start = i + 1
        i += 1
    return start


def _ends_block_header(text, start, colon):
    """Whether ``colon`` ends a compound statement header (``if x: import y``)."""
    head = text[start:colon].lstrip()
    return bool(re.match(r"(if|elif|else|while|for|try|except|finally|with|def|class|async)\b",
                         head))


def _import_context(statement):
    """Classify the cursor at the end of an ``import``/``from`` statement."""
    if statement.startswith("import"):
        items = statement[len("import"):]
        if items and not items[0].isspace():
            return CursorContext(NONE)
        last = items.split(",")[-1].strip()
        match = _IMPORT_ITEM_RE.match(last)
        if not match:
            return CursorContext(NONE)
        return CursorContext(IMPORT_MODULE, match.group(2), module=_dotted(match.group(1)))
    match = _FROM_IMPORT_RE.match(statement)
    if match:
        last = match.group(3).split(",")[-1].strip()
        if not re.match(r"^\w*$", last) or (match.group(3).count("(") > 0):
            return CursorContext(NONE)
        level = match.group(1).count(".")
        module = _dotted(match.group(2))
        if not module and not level:
            return CursorContext(NONE)
        return CursorContext(IMPORT_NAME, last, module=module, level=level)
    match = _FROM_MODULE_RE.match(statement)
    if match and (match.group(1) or statement[len("from"):][:1].isspace()):
        return CursorContext(IMPORT_MODULE, match.group(3), module=_dotted(match.group(2)),
                             level=match.group(1).count("."))
    match = _FROM_KEYWORD_RE.match(statement)
    if match and (match.group(1) or match.group(2)):
        return CursorContext(KEYWORDS, match.group(3), words=["import"])
    return CursorContext(NONE)


def _dotted(text):
    return re.sub(r"\s+", "", text or "")


def _is_ident_char(ch):
    return ch == "_" or ch.isalnum()


def _skip_space_back(text, pos):
    while pos > 0 and text[pos - 1] in " \t":
        pos -= 1
    return pos


def _inside_string_or_comment(text):
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == "#":
            newline = text.find("\n", i)
            if newline < 0:
                return True
            i = newline + 1
        elif ch in "'\"":
            quote = text[i : i + 3] if text[i : i + 3] in ("'''", '"""') else ch
            i += len(quote)
            closed = False
            while i < n:
                if text[i] == "\\":
                    i += 2
                    continue
                if text.startswith(quote, i):
                    i += len(quote)
                    closed = True
                    break
                if text[i] == "\n" and len(quote) == 1:
                    break
                i += 1
            if not closed and i >= n:
                return True
        else:
            i += 1
    return False


def _receiver_before(text, dot):
    """Source text of the primary expression ending just before ``dot``."""
    if dot > 0 and text[dot - 1] == ".":
        return None
    pos = _skip_space_back(text, dot)
    begin = _scan_primary(text, pos)
    if begin is None or begin == pos:
        return None
    receiver = text[begin:pos].strip()
    if receiver and (receiver[0].isdigit() and receiver.replace("_", "").isdigit()):
        return None
    return receiver


def _scan_primary(text, pos):
    """Scan one primary (atom plus trailers) backwards; return its start."""
    while True:
        if pos == 0:
            return None
        ch = text[pos - 1]
        if ch in _CLOSERS:
            opener = _match_open(text, pos - 1)
            if opener is None:
                return None
            pos = opener
            if pos > 0 and (_is_ident_char(text[pos - 1]) or text[pos - 1] in _CLOSERS
                            or text[pos - 1] in "'\""):
                continue
            return _after_dot_chain(text, pos)
        if ch in "'\"":
            start = _match_string_start(text, pos)
            if start is None:
                return None
            return start
        if _is_ident_char(ch):
            while pos > 0 and _is_ident_char(text[pos - 1]):
                pos -= 1
            return _after_dot_chain(text, pos)
        return None


def _after_dot_chain(text, pos):
    """If the atom starting at ``pos`` is preceded by a dot, keep scanning."""
    before = _skip_space_back(text, pos)
    if before > 0 and text[before - 1] == "." and not (before > 1 and text[before - 2] == "."):
        inner = _scan_primary(text, _skip_space_back(text, before - 1))
        return inner if inner is not None else pos
    return pos


def _match_open(text, close_index):
    depth = 0
    i = close_index
    while i >= 0:
        ch = text[i]
        if ch in "'\"":
            start = _match_string_start(text, i + 1)
            if start is None:
                return None
            i = start - 1
            continue
        if ch in _CLOSERS:
            depth += 1
        elif ch in "([{":
            depth -= 1
            if depth == 0:
                return i
        i -= 1
    return None


def _match_string_start(text, end):
    """Given ``text[end - 1]`` is a closing quote, find the literal's start."""
    quote_char = text[end - 1]
    triple = quote_char * 3
    if end >= 3 and text[end - 3 : end] == triple:
        found = text.rfind(triple, 0, end - 3)
        start = found if found >= 0 else None
    else:
        i = end - 2
        start = None
        while i >= 0:
            if text[i] == quote_char and not _escaped(text, i):
                start = i
                break
            if text[i] == "\n":
                break
            i -= 1
    if start is None:
        return None
    head = start
    while head > 0 and start - head < 2 and text[head - 1] in _STRING_PREFIX_CHARS:
        head -= 1
    if head < start and not (head > 0 and _is_ident_char(text[head - 1])):
        return head
    return start


def _escaped(text, i):
    count = 0
    while i - 1 - count >= 0 and text[i - 1 - count] == "\\":
        count += 1
    return count % 2 == 1

